import { useCallback, useEffect, useRef, useState } from 'react';
import confetti from 'canvas-confetti';
import { Game, loadRecords } from './game/engine';
import type { Delivery, DiffId, HudData, MsgKind, Summary } from './game/engine';
import type { UpgradeId, Upgrades } from './game/flight';
import Hud from './components/Hud';
import type { Msg } from './components/Hud';
import { GameOverScreen, HangarScreen, Menu, PauseScreen } from './components/Screens';
import './index.css';

type Screen = 'menu' | 'play' | 'paused' | 'hangar' | 'over';
const PREFS_KEY = 'piloto-carga-prefs';

function loadPrefs(): { diff: DiffId; invert: boolean; muted: boolean } {
  try {
    const p = JSON.parse(localStorage.getItem(PREFS_KEY) || '{}');
    return { diff: p.diff || 'comercial', invert: !!p.invert, muted: !!p.muted };
  } catch { return { diff: 'comercial', invert: false, muted: false }; }
}

export default function App() {
  const wrapRef = useRef<HTMLDivElement>(null);
  const overlayRef = useRef<HTMLCanvasElement>(null);
  const gameRef = useRef<Game | null>(null);
  const timers = useRef<number[]>([]);
  const msgId = useRef(0);
  const [prefs] = useState(loadPrefs);
  const [screen, setScreen] = useState<Screen>('menu');
  const [hud, setHud] = useState<HudData | null>(null);
  const [msgs, setMsgs] = useState<Msg[]>([]);
  const [summary, setSummary] = useState<Summary | null>(null);
  const [delivery, setDelivery] = useState<Delivery | null>(null);
  const [shop, setShop] = useState<{ money: number; upgrades: Upgrades } | null>(null);
  const [diff, setDiff] = useState<DiffId>(prefs.diff);
  const [invert, setInvert] = useState(prefs.invert);
  const [muted, setMuted] = useState(prefs.muted);
  const [records, setRecords] = useState(loadRecords);
  const [touch] = useState(() => typeof window !== 'undefined' && ('ontouchstart' in window || navigator.maxTouchPoints > 0));

  const pushMsg = useCallback((text: string, kind: MsgKind) => {
    const id = ++msgId.current;
    setMsgs(m => [...m.slice(-4), { id, text, kind }]);
    timers.current.push(window.setTimeout(() => setMsgs(m => m.filter(x => x.id !== id)), 2400));
  }, []);

  const togglePause = useCallback(() => {
    const g = gameRef.current; if (!g) return;
    if (g.mode === 'play') { g.pause(); setScreen('paused'); }
    else if (g.mode === 'paused') { g.resume(); setScreen('play'); }
  }, []);

  useEffect(() => {
    if (!wrapRef.current || !overlayRef.current) return;
    const g = new Game(wrapRef.current, overlayRef.current, {
      onHud: setHud,
      onMessage: pushMsg,
      onDelivery: d => {
        setDelivery(d); setShop({ money: d.money, upgrades: d.upgrades }); setScreen('hangar');
        confetti({ particleCount: 90, spread: 70, origin: { y: 0.3 }, colors: ['#f2a21b', '#29d3ff', '#ffffff', '#14213d'] });
      },
      onGameOver: s => {
        setSummary(s); setScreen('over'); setRecords(loadRecords());
        if (s.newRecord) confetti({ particleCount: 150, spread: 90, origin: { y: 0.35 }, colors: ['#f2a21b', '#ffd447', '#29d3ff', '#ffffff'] });
      },
    });
    g.input.onPause = togglePause;
    g.input.onAnyKey = () => g.sfx.unlock();
    gameRef.current = g; (window as any).__game = g;
    return () => {
      timers.current.forEach(t => clearTimeout(t)); timers.current = [];
      g.dispose(); gameRef.current = null;
    };
  }, [pushMsg, togglePause]);

  useEffect(() => { if (gameRef.current) gameRef.current.input.invert = invert; }, [invert]);
  useEffect(() => { gameRef.current?.setMuted(muted); }, [muted]);
  useEffect(() => {
    try { localStorage.setItem(PREFS_KEY, JSON.stringify({ diff, invert, muted })); } catch { /* sin almacenamiento */ }
  }, [diff, invert, muted]);

  const play = () => {
    const g = gameRef.current; if (!g) return;
    setMsgs([]); setHud(null); setSummary(null); setDelivery(null);
    g.input.invert = invert; g.setMuted(muted); g.start(diff);
    setScreen('play');
  };
  const toMenu = () => { gameRef.current?.toMenu(); setHud(null); setMsgs([]); setScreen('menu'); setRecords(loadRecords()); };
  const buy = (id: UpgradeId) => { const g = gameRef.current; if (g) setShop(g.buyUpgrade(id)); };
  const takeoff = () => { const g = gameRef.current; if (!g) return; setMsgs([]); g.continueFlight(); setScreen('play'); };

  return (
    <div className="relative w-full h-screen overflow-hidden bg-[#9cc6ea] select-none" style={{ minHeight: 320 }}>
      <div ref={wrapRef} className="absolute inset-0" onPointerDown={() => gameRef.current?.sfx.unlock()} />
      <canvas ref={overlayRef} className="absolute inset-0 pointer-events-none" />
      {(screen === 'play' || screen === 'paused') && (
        <Hud hud={hud} msgs={msgs} muted={muted} touch={touch} input={gameRef.current?.input ?? null}
          onMute={() => setMuted(m => !m)} onPause={togglePause} />
      )}
      {screen === 'menu' && (
        <Menu diff={diff} setDiff={setDiff} invert={invert} setInvert={setInvert} records={records}
          muted={muted} onMute={() => setMuted(m => !m)} onPlay={play} />
      )}
      {screen === 'paused' && <PauseScreen onResume={togglePause} onRestart={play} onMenu={toMenu} />}
      {screen === 'hangar' && delivery && shop && (
        <HangarScreen d={delivery} money={shop.money} upgrades={shop.upgrades} onBuy={buy} onGo={takeoff} onMenu={toMenu} />
      )}
      {screen === 'over' && summary && <GameOverScreen s={summary} onRetry={play} onMenu={toMenu} />}
    </div>
  );
}

import { useRef } from 'react';
import type { PointerEvent as RPointerEvent } from 'react';
import { ArrowUp, Gauge, MapPin, Package, Pause, Plane, Volume2, VolumeX, Wind } from 'lucide-react';
import clsx from 'clsx';
import type { HudData, MsgKind } from '../game/engine';
import type { Input } from '../game/input';

export interface Msg { id: number; text: string; kind: MsgKind }
interface Props { hud: HudData | null; msgs: Msg[]; muted: boolean; touch: boolean; input: Input | null; onMute: () => void; onPause: () => void }

const NAVY = '#14213d';
const MSG_STYLE: Record<MsgKind, string> = {
  info: 'bg-[#fbf7ee]/95 text-[#14213d]', good: 'bg-emerald-500/95 text-white', bad: 'bg-rose-600/95 text-white', gold: 'bg-amber-400/95 text-[#14213d]',
};

function Bar({ label, value, color, warn }: { label: string; value: number; color: string; warn?: boolean }) {
  const v = Math.max(0, Math.min(1, value));
  return (
    <div className="min-w-0">
      <div className="flex justify-between text-[9px] font-bold tracking-[0.2em] text-[#14213d]/70"><span>{label}</span><span className="tabular-nums">{Math.round(v * 100)}%</span></div>
      <div className={clsx('mt-1 h-2 rounded-full bg-[#14213d]/15 overflow-hidden', warn && 'animate-pulse')}>
        <div className="h-full rounded-full transition-[width] duration-150" style={{ width: `${v * 100}%`, background: color }} />
      </div>
    </div>
  );
}

function Readout({ label, value, unit }: { label: string; value: string | number; unit: string }) {
  return (
    <div className="text-center leading-none">
      <div className="text-[9px] font-bold tracking-[0.25em] text-[#14213d]/60">{label}</div>
      <div className="mt-1 text-2xl font-black tabular-nums" style={{ color: NAVY }}>{value}</div>
      <div className="text-[9px] font-semibold text-[#14213d]/55">{unit}</div>
    </div>
  );
}

export default function Hud({ hud, msgs, muted, touch, input, onMute, onPause }: Props) {
  if (!hud) return null;
  const km = hud.dist >= 1000 ? `${(hud.dist / 1000).toFixed(1)} km` : `${hud.dist} m`;
  return (
    <div className="absolute inset-0 pointer-events-none select-none font-sans">
      {/* Misión */}
      <div className="absolute left-3 top-3 sm:left-4 sm:top-4 w-[min(270px,62vw)] rounded-2xl bg-[#fbf7ee]/90 shadow-[0_8px_30px_rgba(20,33,61,0.25)] ring-1 ring-white/70 px-4 py-3 text-[#14213d]">
        <div className="flex items-center justify-between text-[10px] font-bold tracking-[0.25em] text-amber-600">
          <span>MISIÓN {hud.mission}</span>
          <span className="flex gap-1">{Array.from({ length: 3 }, (_, i) => <Plane key={i} size={13} className={i < hud.lives ? 'text-[#14213d]' : 'text-[#14213d]/20'} />)}</span>
        </div>
        <div className="mt-1 flex items-center gap-1.5 text-sm font-bold"><Package size={14} className="text-amber-600" />{hud.cargo}</div>
        <div className="flex items-center gap-1.5 text-xs text-[#14213d]/75"><MapPin size={13} /> {hud.dest} · <span className="tabular-nums">{km}</span></div>
        <div className="mt-2 flex items-end justify-between">
          <div><div className="text-[9px] font-bold tracking-[0.25em] text-[#14213d]/55">CAJA</div><div className="text-xl font-black tabular-nums">${hud.money.toLocaleString('es-ES')}</div></div>
          <div className="text-right"><div className="text-[9px] font-bold tracking-[0.25em] text-[#14213d]/55">ANILLOS</div><div className="text-lg font-black tabular-nums">{hud.hits}<span className="text-[#14213d]/40">/{hud.total}</span></div></div>
        </div>
      </div>

      {/* Botones */}
      <div className="absolute right-4 top-3 flex gap-2 pointer-events-auto">
        {[{ k: 'm', icon: muted ? <VolumeX size={17} /> : <Volume2 size={17} />, fn: onMute, l: 'Silencio' }, { k: 'p', icon: <Pause size={17} />, fn: onPause, l: 'Pausa' }].map(b => (
          <button key={b.k} aria-label={b.l} onClick={b.fn} className="h-9 w-9 grid place-items-center rounded-full bg-[#fbf7ee]/90 text-[#14213d] shadow ring-1 ring-white/70 hover:bg-white">{b.icon}</button>
        ))}
      </div>

      {/* Mensajes y avisos */}
      <div className="absolute top-[14%] left-0 right-0 flex flex-col items-center gap-2 px-4">
        {msgs.slice(-3).map(m => (
          <div key={m.id} className={clsx('rounded-full px-5 py-1.5 text-sm font-bold shadow-lg', MSG_STYLE[m.kind])}>{m.text}</div>
        ))}
      </div>
      {hud.warn && (
        <div className={clsx('absolute left-1/2 -translate-x-1/2 top-[34%] rounded-lg px-5 py-2 text-base sm:text-lg font-black tracking-[0.2em] shadow-xl',
          hud.warn === 'TORMENTA' ? 'bg-slate-800/85 text-sky-100' : 'bg-rose-600/90 text-white animate-pulse')}>{hud.warn}</div>
      )}

      {/* Panel de instrumentos */}
      <div className={clsx('absolute left-1/2 -translate-x-1/2 rounded-2xl bg-[#fbf7ee]/90 shadow-[0_10px_40px_rgba(20,33,61,0.3)] ring-1 ring-white/70 px-4 py-3',
        touch ? 'bottom-2 w-[min(560px,58vw)] min-w-[300px] scale-[0.8] origin-bottom' : 'bottom-4 w-[min(620px,94vw)]')}>
        <div className="grid grid-cols-4 gap-2 items-center">
          <Readout label="VELOCIDAD" value={hud.speed} unit="km/h" />
          <Readout label="ALTURA" value={hud.alt} unit="m sobre suelo" />
          <Readout label="VARIÓMETRO" value={(hud.vs > 0 ? '+' : '') + hud.vs.toFixed(1)} unit="m/s" />
          <div className="flex flex-col items-center leading-none">
            <div className="text-[9px] font-bold tracking-[0.25em] text-[#14213d]/60 flex items-center gap-1"><Wind size={10} />VIENTO</div>
            <div className="mt-1 h-8 w-8 rounded-full ring-2 ring-[#14213d]/20 grid place-items-center">
              <ArrowUp size={20} strokeWidth={3} className="text-sky-600 transition-transform" style={{ transform: `rotate(${(-hud.windRel * 180) / Math.PI}deg)` }} />
            </div>
            <div className="mt-0.5 text-[10px] font-bold tabular-nums text-[#14213d]">{hud.windKmh} km/h</div>
          </div>
        </div>
        <div className="mt-2.5 grid grid-cols-3 gap-3">
          <Bar label="COMBUSTIBLE" value={hud.fuel} color="linear-gradient(90deg,#f2a21b,#ffcf5a)" warn={hud.fuel < 0.2} />
          <Bar label="FUSELAJE" value={hud.hull} color={hud.hull > 0.4 ? 'linear-gradient(90deg,#16a37f,#49d6a5)' : '#e5484d'} warn={hud.hull < 0.3} />
          <Bar label="CARGA" value={hud.cargoInt / 100} color="linear-gradient(90deg,#2563eb,#5ab0ff)" />
        </div>
        <div className="mt-2 flex items-center justify-center gap-2 text-[10px] font-bold tracking-[0.2em]">
          <span className={clsx('rounded-full px-2 py-0.5', hud.turbo ? 'bg-amber-500 text-white' : 'bg-[#14213d]/10 text-[#14213d]/45')}>TURBO</span>
          <span className={clsx('rounded-full px-2 py-0.5', hud.flaps ? 'bg-sky-600 text-white' : 'bg-[#14213d]/10 text-[#14213d]/45')}>FLAPS</span>
          <span className={clsx('rounded-full px-2 py-0.5 flex items-center gap-1', hud.approach ? 'bg-emerald-500 text-white' : 'bg-[#14213d]/10 text-[#14213d]/45')}><Gauge size={10} />APROXIMACIÓN</span>
          <span className={clsx('rounded-full px-2 py-0.5 tabular-nums', hud.time > hud.par ? 'bg-rose-500/15 text-rose-600' : 'bg-[#14213d]/10 text-[#14213d]/70')}>{Math.floor(hud.time)}s / {Math.round(hud.par)}s</span>
        </div>
      </div>

      {touch && input && <TouchControls input={input} />}
    </div>
  );
}

function TouchControls({ input }: { input: Input }) {
  const base = useRef<HTMLDivElement>(null); const knob = useRef<HTMLDivElement>(null);
  const move = (e: RPointerEvent) => {
    const r = base.current!.getBoundingClientRect(), rad = r.width / 2;
    let dx = (e.clientX - r.left - rad) / rad, dy = (e.clientY - r.top - rad) / rad; const l = Math.hypot(dx, dy); if (l > 1) { dx /= l; dy /= l; }
    input.touch.active = true; input.touch.roll = dx; input.touch.pitch = -dy;
    if (knob.current) knob.current.style.transform = `translate(${dx * rad * 0.6}px, ${dy * rad * 0.6}px)`;
  };
  const end = () => { input.touch.active = false; input.touch.roll = 0; input.touch.pitch = 0; if (knob.current) knob.current.style.transform = ''; };
  const hold = (k: 'turbo' | 'flaps', v: boolean) => () => { input.touch[k] = v; };
  const btn = 'h-16 w-16 rounded-full grid place-items-center text-[11px] font-black tracking-wider shadow-lg ring-2 ring-white/70 active:scale-95';
  return (
    <>
      <div ref={base} className="pointer-events-auto absolute left-5 bottom-5 h-36 w-36 rounded-full bg-[#fbf7ee]/35 ring-2 ring-white/70 touch-none grid place-items-center"
        onPointerDown={e => { (e.target as HTMLElement).setPointerCapture?.(e.pointerId); move(e); }} onPointerMove={e => { if (input.touch.active) move(e); }}
        onPointerUp={end} onPointerCancel={end}>
        <div ref={knob} className="h-14 w-14 rounded-full bg-[#fbf7ee]/95 shadow-lg ring-2 ring-[#14213d]/20" />
      </div>
      <div className="pointer-events-auto absolute right-5 bottom-5 flex gap-3 touch-none">
        <button className={clsx(btn, 'bg-sky-600/90 text-white')} onPointerDown={hold('flaps', true)} onPointerUp={hold('flaps', false)} onPointerLeave={hold('flaps', false)}>FLAPS</button>
        <button className={clsx(btn, 'bg-amber-500/95 text-white')} onPointerDown={hold('turbo', true)} onPointerUp={hold('turbo', false)} onPointerLeave={hold('turbo', false)}>TURBO</button>
      </div>
    </>
  );
}

import { Check, Fuel, Home, Package, Play, PlaneLanding, PlaneTakeoff, RotateCcw, Shield, Trophy, Volume2, VolumeX, Wrench, Zap } from 'lucide-react';
import clsx from 'clsx';
import type { ReactNode } from 'react';
import { DIFFS } from '../game/engine';
import type { Delivery, DiffId, Summary } from '../game/engine';
import { UPGRADES } from '../game/flight';
import type { UpgradeId, Upgrades } from '../game/flight';

const TITLE = { fontFamily: '"Avenir Next Condensed", "Futura", "Arial Narrow", "Roboto Condensed", system-ui, sans-serif' };
const CARD = 'rounded-3xl bg-[#fbf7ee]/95 text-[#14213d] shadow-[0_20px_60px_rgba(20,33,61,0.35)] ring-1 ring-white/80';
const BTN = 'flex items-center justify-center gap-2 rounded-2xl px-5 py-3 font-black tracking-wide transition active:scale-[0.98]';
const PRIMARY = clsx(BTN, 'bg-gradient-to-b from-amber-400 to-amber-500 text-[#14213d] shadow-[0_8px_24px_rgba(242,162,27,0.45)] hover:from-amber-300');
const GHOST = clsx(BTN, 'bg-[#14213d]/[0.08] ring-1 ring-[#14213d]/15 hover:bg-[#14213d]/[0.12]');
const money = (n: number) => '$' + n.toLocaleString('es-ES');

const KEYS: Array<[string, string]> = [
  ['↑ ↓ / W S', 'Subir / bajar el morro'], ['← → / A D', 'Alabear y virar'], ['Shift', 'Turbo (gasta más)'],
  ['Espacio / F', 'Flaps y frenos'], ['P / Esc', 'Pausa'],
];

interface MenuProps {
  diff: DiffId; setDiff: (d: DiffId) => void; invert: boolean; setInvert: (v: boolean) => void;
  records: Record<DiffId, number>; muted: boolean; onMute: () => void; onPlay: () => void;
}

export function Menu({ diff, setDiff, invert, setInvert, records, muted, onMute, onPlay }: MenuProps) {
  return (
    <div className="absolute inset-0 overflow-y-auto bg-gradient-to-r from-[#0f2a52]/55 via-[#0f2a52]/10 to-transparent">
      <div className="min-h-full flex items-center p-4 sm:p-10">
        <div className={clsx(CARD, 'w-full max-w-[470px] p-6 sm:p-8')}>
          <div className="flex items-center gap-2 text-[10px] font-bold tracking-[0.4em] text-amber-600"><PlaneLanding size={14} /> AEROCARGA DE MONTAÑA</div>
          <h1 style={TITLE} className="mt-2 text-5xl sm:text-6xl font-black leading-[0.9] tracking-tight">
            PILOTO<br /><span className="text-amber-500">DE CARGA</span>
          </h1>
          <p className="mt-3 text-sm leading-relaxed text-[#14213d]/75">
            Amanece despejado sobre la cordillera. Carga tu bimotor, sigue los anillos de ruta por los valles, vigila el combustible y el
            viento, y posa el avión en pistas de montaña para cobrar cada entrega.
          </p>
          <div className="mt-5 text-[10px] font-bold tracking-[0.3em] text-[#14213d]/55">LICENCIA</div>
          <div className="mt-2 grid grid-cols-3 gap-2">
            {(Object.keys(DIFFS) as DiffId[]).map(id => (
              <button key={id} onClick={() => setDiff(id)}
                className={clsx('rounded-2xl px-3 py-2.5 text-left ring-1 transition', diff === id ? 'bg-[#14213d] text-white ring-[#14213d] shadow-lg' : 'bg-white/60 ring-[#14213d]/15 hover:bg-white')}>
                <div style={TITLE} className="font-black tracking-wide">{DIFFS[id].label}</div>
                <div className={clsx('text-[10px] leading-tight', diff === id ? 'text-white/70' : 'text-[#14213d]/60')}>{DIFFS[id].sub}</div>
                <div className={clsx('mt-1 text-[10px] font-bold tabular-nums flex items-center gap-1', diff === id ? 'text-amber-300' : 'text-amber-600')}><Trophy size={10} />{money(records[id])}</div>
              </button>
            ))}
          </div>
          <div className="mt-4 grid grid-cols-[auto,1fr] gap-x-3 gap-y-1 text-xs">
            {KEYS.flatMap(([k, d]) => [
              <kbd key={'k' + k} className="rounded-md bg-[#14213d]/[0.08] px-2 py-0.5 font-mono font-bold text-[#14213d] whitespace-nowrap">{k}</kbd>,
              <span key={'d' + k} className="text-[#14213d]/70 self-center">{d}</span>])}
          </div>
          <div className="mt-4 flex items-center justify-between gap-3">
            <label className="flex items-center gap-2 text-xs text-[#14213d]/75 cursor-pointer">
              <input type="checkbox" checked={invert} onChange={e => setInvert(e.target.checked)} className="accent-amber-500 h-4 w-4" />
              Invertir eje (como un piloto real)
            </label>
            <button aria-label="Silencio" onClick={onMute} className="h-9 w-9 grid place-items-center rounded-full bg-[#14213d]/[0.08] ring-1 ring-[#14213d]/15">
              {muted ? <VolumeX size={16} /> : <Volume2 size={16} />}
            </button>
          </div>
          <button onClick={onPlay} className={clsx(PRIMARY, 'mt-5 w-full text-lg')}><Play size={20} fill="currentColor" /> Jugar</button>
          <p className="mt-3 text-[11px] text-[#14213d]/50 text-center">Consejo: en la aproximación usa los flaps y sigue las luces PAPI (2 blancas + 2 rojas).</p>
        </div>
      </div>
    </div>
  );
}

function Overlay({ children }: { children: ReactNode }) {
  return <div className="absolute inset-0 overflow-y-auto bg-[#0f2a52]/35 backdrop-blur-[2px]"><div className="min-h-full grid place-items-center p-4">{children}</div></div>;
}

export function PauseScreen({ onResume, onRestart, onMenu }: { onResume: () => void; onRestart: () => void; onMenu: () => void }) {
  return (
    <Overlay>
      <div className={clsx(CARD, 'w-full max-w-sm p-7 text-center')}>
        <div style={TITLE} className="text-4xl font-black">EN ESPERA</div>
        <p className="mt-1 text-sm text-[#14213d]/60">La torre mantiene tu plan de vuelo.</p>
        <div className="mt-5 grid gap-2">
          <button onClick={onResume} className={PRIMARY}><Play size={18} fill="currentColor" /> Continuar</button>
          <button onClick={onRestart} className={GHOST}><RotateCcw size={18} /> Reiniciar</button>
          <button onClick={onMenu} className={GHOST}><Home size={18} /> Menú</button>
        </div>
      </div>
    </Overlay>
  );
}

const UP_ICON: Record<UpgradeId, ReactNode> = { motor: <Zap size={18} />, tanque: <Fuel size={18} />, fuselaje: <Shield size={18} />, bodega: <Package size={18} /> };

function Line({ label, value, tone }: { label: string; value: string; tone?: 'good' | 'bad' }) {
  return (
    <div className="flex justify-between gap-3 border-b border-dashed border-[#14213d]/15 py-1.5 text-sm">
      <span className="text-[#14213d]/70">{label}</span>
      <span className={clsx('font-bold tabular-nums', tone === 'good' && 'text-emerald-600', tone === 'bad' && 'text-rose-600')}>{value}</span>
    </div>
  );
}

interface HangarProps { d: Delivery; money: number; upgrades: Upgrades; onBuy: (id: UpgradeId) => void; onGo: () => void; onMenu: () => void }

export function HangarScreen({ d, money: cash, upgrades, onBuy, onGo, onMenu }: HangarProps) {
  return (
    <Overlay>
      <div className="w-full max-w-4xl grid gap-4 md:grid-cols-[1fr,1.25fr]">
        <div className={clsx(CARD, 'p-6')}>
          <div className="flex items-center gap-2 text-[10px] font-bold tracking-[0.35em] text-emerald-600"><Check size={14} /> ENTREGA COMPLETADA</div>
