/** Audio procedural (Web Audio): turbohélice, anillos, entregas, avisos, impactos y truenos. */
export class Sfx {
  ctx: AudioContext | null = null;
  private master: GainNode | null = null;
  private noise: AudioBuffer | null = null;
  private eng: { o1: OscillatorNode; o2: OscillatorNode; gain: GainNode; f: BiquadFilterNode; src: AudioBufferSourceNode } | null = null;
  private warnT = 0;
  muted = false;

  unlock() {
    if (this.ctx) { if (this.ctx.state === 'suspended') this.ctx.resume().catch(() => {}); return; }
    const AC: typeof AudioContext | undefined = (window as any).AudioContext || (window as any).webkitAudioContext;
    if (!AC) return;
    try { this.ctx = new AC(); } catch { return; }
    this.master = this.ctx.createGain(); this.master.gain.value = this.muted ? 0 : 0.5; this.master.connect(this.ctx.destination);
    const len = this.ctx.sampleRate * 1.5; this.noise = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
    const d = this.noise.getChannelData(0); for (let i = 0; i < len; i++) d[i] = Math.random() * 2 - 1;
  }

  setMuted(m: boolean) {
    this.muted = m;
    if (this.master && this.ctx) this.master.gain.setTargetAtTime(m ? 0 : 0.5, this.ctx.currentTime, 0.05);
  }

  startEngine() {
    if (!this.ctx || !this.master || this.eng || !this.noise) return;
    const c = this.ctx, gain = c.createGain(), f = c.createBiquadFilter();
    gain.gain.value = 0; f.type = 'lowpass'; f.frequency.value = 420;
    const o1 = c.createOscillator(); o1.type = 'sawtooth'; o1.frequency.value = 52;
    const o2 = c.createOscillator(); o2.type = 'triangle'; o2.frequency.value = 104.7;
    const src = c.createBufferSource(); src.buffer = this.noise; src.loop = true;
    const bp = c.createBiquadFilter(); bp.type = 'bandpass'; bp.frequency.value = 1300; bp.Q.value = 0.7;
    const ng = c.createGain(); ng.gain.value = 0.35;
    o1.connect(f); o2.connect(f); src.connect(bp); bp.connect(ng); ng.connect(f); f.connect(gain); gain.connect(this.master);
    o1.start(); o2.start(); src.start();
    gain.gain.setTargetAtTime(0.11, c.currentTime, 0.5);
    this.eng = { o1, o2, gain, f, src };
  }

  setEngine(speedK: number, turbo: boolean, out: boolean) {
    if (!this.ctx || !this.eng) return;
    const t = this.ctx.currentTime, fr = out ? 18 : 46 + speedK * 26 + (turbo ? 22 : 0);
    this.eng.o1.frequency.setTargetAtTime(fr, t, 0.25); this.eng.o2.frequency.setTargetAtTime(fr * 2.01, t, 0.25);
    this.eng.f.frequency.setTargetAtTime(turbo ? 1100 : 480, t, 0.3);
    this.eng.gain.gain.setTargetAtTime(out ? 0.03 : 0.11, t, 0.4);
  }

  stopEngine() {
    if (!this.eng || !this.ctx) return;
    const e = this.eng; this.eng = null;
    e.gain.gain.setTargetAtTime(0, this.ctx.currentTime, 0.15);
    setTimeout(() => { try { e.o1.stop(); e.o2.stop(); e.src.stop(); } catch { /* ya parado */ } }, 600);
  }

  private tone(freq: number, dur: number, type: OscillatorType = 'sine', vol = 0.2, delay = 0, slide = 0) {
    if (!this.ctx || !this.master) return;
    const c = this.ctx, t = c.currentTime + delay, o = c.createOscillator(), g = c.createGain();
    o.type = type; o.frequency.setValueAtTime(freq, t);
    if (slide) o.frequency.exponentialRampToValueAtTime(Math.max(20, freq + slide), t + dur);
    g.gain.setValueAtTime(0.0001, t); g.gain.exponentialRampToValueAtTime(vol, t + 0.012); g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    o.connect(g); g.connect(this.master); o.start(t); o.stop(t + dur + 0.05);
  }

  private burst(dur: number, freq: number, vol = 0.4, type: BiquadFilterType = 'lowpass', delay = 0) {
    if (!this.ctx || !this.master || !this.noise) return;
    const c = this.ctx, t = c.currentTime + delay, s = c.createBufferSource(), f = c.createBiquadFilter(), g = c.createGain();
    s.buffer = this.noise; f.type = type; f.frequency.value = freq;
    g.gain.setValueAtTime(vol, t); g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    s.connect(f); f.connect(g); g.connect(this.master); s.start(t); s.stop(t + dur + 0.05);
  }

  ring(streak: number) { const b = 660 * Math.pow(1.06, Math.min(streak, 10)); this.tone(b, 0.18, 'triangle', 0.18); this.tone(b * 1.5, 0.28, 'sine', 0.14, 0.07); }
  gold() { [0, 0.06, 0.12, 0.18].forEach((d, i) => this.tone(880 * [1, 1.25, 1.5, 2][i], 0.25, 'triangle', 0.16, d)); }
  miss() { this.tone(300, 0.25, 'square', 0.07, 0, -120); }
  pickup() { this.tone(520, 0.12, 'sine', 0.2); this.tone(780, 0.2, 'sine', 0.18, 0.08); this.burst(0.25, 3000, 0.08, 'highpass'); }
  hit() { this.burst(0.3, 700, 0.5); this.tone(110, 0.25, 'square', 0.12, 0, -50); }
  explode() { this.burst(1.6, 420, 0.9); this.tone(70, 1.1, 'sawtooth', 0.25, 0, -45); }
  screech() { this.burst(0.5, 2400, 0.22, 'bandpass'); this.tone(90, 0.2, 'sine', 0.3, 0, -40); }
  thunder() { this.burst(2.2, 180, 0.6, 'lowpass', 0.15); }
  gust() { this.burst(1.4, 600, 0.18, 'bandpass'); }
  cash() { [0, 0.09, 0.18].forEach((d, i) => this.tone([988, 1319, 1976][i], 0.35, 'triangle', 0.15, d)); this.burst(0.15, 5000, 0.08, 'highpass', 0.25); }
  warn(dt: number) { this.warnT -= dt; if (this.warnT <= 0) { this.warnT = 0.45; this.tone(1180, 0.14, 'square', 0.07); } }

  dispose() { this.stopEngine(); const c = this.ctx; this.ctx = null; if (c) setTimeout(() => c.close().catch(() => {}), 700); }
}

import * as THREE from 'three';
import { radialTex } from './props';

/** Partículas en un único THREE.Points (pool circular) + estelas de viento alrededor de la cámara. */
export class Particles {
  points: THREE.Points;
  private geo = new THREE.BufferGeometry();
  private mat: THREE.ShaderMaterial;
  private tex: THREE.Texture;
  private pos: Float32Array; private colr: Float32Array; private size: Float32Array; private alpha: Float32Array;
  private vel: Float32Array; private life: Float32Array; private max: Float32Array; private grow: Float32Array;
  private cursor = 0;

  constructor(private n: number, additive: boolean) {
    this.pos = new Float32Array(n * 3); this.colr = new Float32Array(n * 3); this.vel = new Float32Array(n * 3);
    this.size = new Float32Array(n); this.alpha = new Float32Array(n); this.life = new Float32Array(n); this.max = new Float32Array(n); this.grow = new Float32Array(n);
    this.geo.setAttribute('position', new THREE.BufferAttribute(this.pos, 3));
    this.geo.setAttribute('color', new THREE.BufferAttribute(this.colr, 3));
    this.geo.setAttribute('size', new THREE.BufferAttribute(this.size, 1));
    this.geo.setAttribute('alpha', new THREE.BufferAttribute(this.alpha, 1));
    this.tex = radialTex([[0, 'rgba(255,255,255,1)'], [0.4, 'rgba(255,255,255,0.55)'], [1, 'rgba(255,255,255,0)']], 64);
    this.mat = new THREE.ShaderMaterial({
      uniforms: { map: { value: this.tex }, scale: { value: 500 } },
      vertexShader: `attribute float size; attribute float alpha; attribute vec3 color; varying vec3 vC; varying float vA; uniform float scale;
        void main(){ vC = color; vA = alpha; vec4 mv = modelViewMatrix * vec4(position, 1.0); gl_PointSize = size * scale / max(1.0, -mv.z); gl_Position = projectionMatrix * mv; }`,
      fragmentShader: `uniform sampler2D map; varying vec3 vC; varying float vA;
        void main(){ vec4 t = texture2D(map, gl_PointCoord); gl_FragColor = vec4(vC, t.a * vA); if (gl_FragColor.a < 0.01) discard; }`,
      transparent: true, depthWrite: false, blending: additive ? THREE.AdditiveBlending : THREE.NormalBlending,
    });
    this.points = new THREE.Points(this.geo, this.mat); this.points.frustumCulled = false;
  }

  setScale(h: number) { this.mat.uniforms.scale.value = h * 0.6; }

  emit(p: THREE.Vector3, v: THREE.Vector3, color: THREE.Color, size: number, life: number, grow = 1) {
    const i = this.cursor; this.cursor = (this.cursor + 1) % this.n;
    this.pos.set([p.x, p.y, p.z], i * 3); this.vel.set([v.x, v.y, v.z], i * 3); this.colr.set([color.r, color.g, color.b], i * 3);
    this.size[i] = size; this.life[i] = life; this.max[i] = life; this.grow[i] = grow;
  }

  burst(p: THREE.Vector3, count: number, speed: number, color: THREE.Color, size: number, life: number, grow = 1, up = 0) {
    const v = new THREE.Vector3();
    for (let i = 0; i < count; i++) {
      v.set(Math.random() - 0.5, Math.random() - 0.5 + up, Math.random() - 0.5).normalize().multiplyScalar(speed * (0.3 + Math.random() * 0.7));
      this.emit(p, v, color, size * (0.6 + Math.random() * 0.8), life * (0.6 + Math.random() * 0.6), grow);
    }
  }

  update(dt: number) {
    const drag = Math.exp(-1.6 * dt);
    for (let i = 0; i < this.n; i++) {
      if (this.life[i] <= 0) { this.alpha[i] = 0; continue; }
      this.life[i] -= dt;
      const k = i * 3;
      this.vel[k] *= drag; this.vel[k + 1] *= drag; this.vel[k + 2] *= drag;
      this.pos[k] += this.vel[k] * dt; this.pos[k + 1] += this.vel[k + 1] * dt; this.pos[k + 2] += this.vel[k + 2] * dt;
      const t = Math.max(0, this.life[i] / this.max[i]);
      this.alpha[i] = Math.min(1, t * 2.2) * (t > 0.92 ? (1 - t) * 12 : 1);
      this.size[i] *= 1 + (this.grow[i] - 1) * dt;
    }
    (['position', 'alpha', 'size', 'color'] as const).forEach(a => { (this.geo.attributes[a] as THREE.BufferAttribute).needsUpdate = true; });
  }

  clear() { this.life.fill(0); this.alpha.fill(0); }
  dispose() { this.geo.dispose(); this.mat.dispose(); this.tex.dispose(); }
}

/** Líneas de viento que se desplazan con la brisa: hacen visible la dirección e intensidad. */
export class WindStreaks {
  lines: THREE.LineSegments;
  private geo = new THREE.BufferGeometry();
  private mat = new THREE.LineBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.35, depthWrite: false });
  private seeds: THREE.Vector3[] = [];
  private arr: Float32Array;
  constructor(private n = 90) {
    this.arr = new Float32Array(n * 6);
    for (let i = 0; i < n; i++) this.seeds.push(new THREE.Vector3((Math.random() - 0.5) * 240, (Math.random() - 0.5) * 120, (Math.random() - 0.5) * 240));
    this.geo.setAttribute('position', new THREE.BufferAttribute(this.arr, 3));
    this.lines = new THREE.LineSegments(this.geo, this.mat); this.lines.frustumCulled = false;
  }
  update(dt: number, center: THREE.Vector3, rel: THREE.Vector3, strength: number) {
    const len = Math.min(14, 2 + rel.length() * 0.12);
    const d = rel.clone().normalize();
    for (let i = 0; i < this.n; i++) {
      const s = this.seeds[i]; s.addScaledVector(rel, dt);
      for (const ax of ['x', 'y', 'z'] as const) { const L = ax === 'y' ? 60 : 120; if (s[ax] > L) s[ax] -= 2 * L; if (s[ax] < -L) s[ax] += 2 * L; }
      const o = i * 6, x = center.x + s.x, y = center.y + s.y, z = center.z + s.z;
      this.arr[o] = x; this.arr[o + 1] = y; this.arr[o + 2] = z;
      this.arr[o + 3] = x - d.x * len; this.arr[o + 4] = y - d.y * len; this.arr[o + 5] = z - d.z * len;
    }
    (this.geo.attributes.position as THREE.BufferAttribute).needsUpdate = true;
    this.mat.opacity = 0.08 + Math.min(0.32, strength * 0.03);
  }
  dispose() { this.geo.dispose(); this.mat.dispose(); }
}

