    this.plane.group.rotation.order = 'YXZ';
    const st = radialTex([[0, 'rgba(0,0,0,0.55)'], [0.6, 'rgba(0,0,0,0.25)'], [1, 'rgba(0,0,0,0)']], 64);
    this.shadow = new THREE.Mesh(new THREE.PlaneGeometry(1, 1), new THREE.MeshBasicMaterial({ map: st, transparent: true, depthWrite: false }));
    this.shadow.geometry.rotateX(-Math.PI / 2); this.shadow.scale.set(22, 1, 17); s.add(this.shadow);
    this.input.attach();
    this.ro = new ResizeObserver(() => this.resize()); this.ro.observe(host); this.resize();
    this.windAng = 1.2; this.windStr = 3;
    this.loop = this.loop.bind(this); this.raf = requestAnimationFrame(this.loop);
  }

  private resize() {
    const w = Math.max(1, this.host.clientWidth), h = Math.max(1, this.host.clientHeight), dpr = Math.min(window.devicePixelRatio || 1, 2);
    this.renderer.setSize(w, h, false); this.camera.aspect = w / h; this.camera.updateProjectionMatrix();
    this.overlay.width = w * dpr; this.overlay.height = h * dpr; this.overlay.style.width = w + 'px'; this.overlay.style.height = h + 'px';
    this.ctx?.setTransform(dpr, 0, 0, dpr, 0, 0);
    this.smoke.setScale(h); this.sparks.setScale(h);
  }

  // ---------------- Flujo de partida ----------------
  start(diff: DiffId) {
    this.diff = diff; this.money = 0; this.earned = 0; this.lives = 3; this.missionNo = 1; this.fromIdx = 0;
    this.upg = { motor: 0, tanque: 0, fuselaje: 0, bodega: 0 }; this.stats2 = { delivered: 0, rings: 0, perfect: 0 };
    this.input.reset(); this.smoke.clear(); this.sparks.clear(); this.sfx.unlock(); this.sfx.startEngine();
    this.pending?.dispose(); this.pending = null;
    this.beginMission(new Mission(this.terrain, 1, 0, diff, 3));
  }

  private beginMission(m: Mission) {
    this.mission?.dispose(); this.mission = m; this.scene.add(m.group);
    this.stats = statsFor(this.upg, DIFFS[this.diff].burn);
    this.flight.fuel = this.stats.fuelCap; this.flight.hull = this.stats.hullCap; this.cargoInt = 100;
    const ap = m.from;
    this.flight.reset(ap.x + ap.fx * (ap.len / 2 + 70), ap.h + 42, ap.z + ap.fz * (ap.len / 2 + 70), ap.dir, this.stats.cruise);
    this.windAng = Math.random() * Math.PI * 2; this.windStr = Math.min(11, (1.5 + m.index * 0.8) * DIFFS[this.diff].wind); this.gust = 0; this.gustT = 6;
    this.prev.copy(this.flight.pos); this.plane.group.visible = true; this.snapCamera(); this.mode = 'play';
    this.cb.onMessage(`Misión ${m.index}: ${m.cargo.name} → ${m.to.name}`, 'info');
  }

  continueFlight() { if (this.mode === 'hangar' && this.pending) { const m = this.pending; this.pending = null; this.sfx.startEngine(); this.beginMission(m); } }

  buyUpgrade(id: UpgradeId) {
    const lv = this.upg[id], cost = UPGRADES[id].cost[lv];
    if (lv < 3 && this.money >= cost) { this.money -= cost; this.upg = { ...this.upg, [id]: lv + 1 }; this.sfx.pickup(); }
    return { money: this.money, upgrades: this.upg };
  }

  pause() { if (this.mode === 'play') { this.mode = 'paused'; this.input.reset(); } }
  resume() { if (this.mode === 'paused') { this.mode = 'play'; this.last = performance.now(); } }
  toMenu() { this.mission?.dispose(); this.mission = null; this.pending?.dispose(); this.pending = null; this.mode = 'menu'; this.sfx.stopEngine(); this.plane.group.visible = true; }
  setMuted(m: boolean) { this.sfx.setMuted(m); }

  private damage(v: number, why: string | null) {
    if (this.mode !== 'play') return;
    this.flight.hull -= v; this.cargoInt = Math.max(0, this.cargoInt - v * (this.mission?.cargo.fragile ?? 1) * 0.45);
    this.dmgFlash = Math.min(1, this.dmgFlash + v * 0.06); this.shake = Math.max(this.shake, Math.min(1, v * 0.08));
    if (why) { this.sfx.hit(); this.cb.onMessage(why, 'bad'); }
    if (this.flight.hull <= 0) this.crash('El fuselaje no resistió');
  }

  private crash(reason: string) {
    if (this.mode !== 'play' && this.mode !== 'rollout') return;
    this.mode = 'crash'; this.crashT = 0; this.lives--; this.shake = 1.6; this.plane.group.visible = false;
    this.cargoInt = Math.max(0, this.cargoInt - 30 * (this.mission?.cargo.fragile ?? 1));
    const p = this.flight.pos;
    this.sparks.burst(p, 90, 45, C.fire, 9, 1.2, 1.4, 0.3); this.sparks.burst(p, 40, 25, C.fire2, 14, 1.6, 1.2, 0.5);
    this.smoke.burst(p, 70, 18, C.smoke, 16, 3.5, 1.8, 0.8);
    this.sfx.explode(); this.cb.onMessage(reason, 'bad');
  }

  private respawn() {
    const m = this.mission!; const r = m.next > 0 ? m.route[m.next - 1] : null;
    if (r) this.flight.reset(r.pos.x - r.n.x * 30, r.pos.y + 6, r.pos.z - r.n.z * 30, Math.atan2(r.n.x, r.n.z), this.stats.cruise);
    else { const ap = m.from; this.flight.reset(ap.x + ap.fx * (ap.len / 2 + 70), ap.h + 42, ap.z + ap.fz * (ap.len / 2 + 70), ap.dir, this.stats.cruise); }
    this.flight.fuel = Math.max(this.flight.fuel, this.stats.fuelCap * 0.45); this.flight.hull = Math.max(this.flight.hull, this.stats.hullCap * 0.6);
    this.prev.copy(this.flight.pos); this.plane.group.visible = true; this.mode = 'play'; this.snapCamera();
    this.cb.onMessage(`Avión de reserva en vuelo · quedan ${this.lives}`, 'info');
  }

  private touchdown(rw: Airport) {
    const f = this.flight, L = DIFFS[this.diff].land, vs = -f.vel.y, m = this.mission!;
    if (vs > 9.5 * L || Math.abs(f.roll) > 0.55 || f.pitch < -0.3) { this.crash('¡Aterrizaje demasiado duro!'); return; }
    f.onGround = true; this.sfx.screech(); this.shake = Math.min(1, vs * 0.1);
    for (const s of [-1, 1]) this.smoke.burst(this.plane.group.localToWorld(new THREE.Vector3(s * 1.9, -2.4, 0.3)), 8, 4, C.puff, 5, 1.4, 2);
    if (rw !== m.to || this.mode !== 'play') { if (rw !== m.to) this.cb.onMessage(`Pista equivocada: tu destino es ${m.to.name}`, 'bad'); return; }
    const g = vs < 2.2 * L && Math.abs(f.roll) < 0.14 ? ['¡Perfecto!', 1.3] : vs < 4 * L ? ['Suave', 1.12] : vs < 6.5 * L ? ['Firme', 1] : ['Duro', 0.85];
    if (g[1] === 0.85) this.cargoInt = Math.max(0, this.cargoInt - 12 * m.cargo.fragile);
    this.landing = { grade: g[0] as string, mul: g[1] as number }; this.mode = 'rollout'; this.rollT = 0;
    this.cb.onMessage(`Aterrizaje ${this.landing.grade.toLowerCase()} en ${rw.name}`, 'good');
  }

  private finishDelivery() {
    const m = this.mission!, base = Math.round((m.distance / 1000) * 110 * m.cargo.pay);
    const ringBonus = m.hits * 20 - m.misses * 25, timeBonus = Math.max(0, Math.round((m.par - m.time) * 4));
    const raw = (base + ringBonus + m.goldCash + timeBonus) * this.landing.mul * (0.3 + 0.7 * this.cargoInt / 100) * (1 + 0.15 * this.upg.bodega);
    const total = Math.max(60, Math.round(raw));
    this.money += total; this.earned += total; this.stats2.delivered++; this.stats2.rings += m.hits;
    if (this.landing.mul >= 1.3) this.stats2.perfect++;
    this.fromIdx = m.to.id; this.missionNo++;
    this.pending = new Mission(this.terrain, this.missionNo, this.fromIdx, this.diff, 3);
    const n = this.pending;
    this.mode = 'hangar'; this.sfx.stopEngine(); this.sfx.cash();
    this.cb.onDelivery({
      mission: m.index, cargo: m.cargo.name, dest: m.to.name, base, hits: m.hits, misses: m.misses, ringBonus, goldCash: m.goldCash, timeBonus,
      grade: this.landing.grade, gradeMul: this.landing.mul, integrity: Math.round(this.cargoInt), total, money: this.money, upgrades: this.upg,
      next: { mission: n.index, cargo: n.cargo.name, from: n.from.name, dest: n.to.name, km: Math.round(n.distance / 100) / 10, legs: n.legs },
    });
  }

  private gameOver() {
    this.mode = 'over'; this.sfx.stopEngine();
    const rec = loadRecords(), best = Math.max(rec[this.diff], this.earned), newRecord = this.earned > rec[this.diff] && this.earned > 0;
    if (newRecord) { rec[this.diff] = this.earned; try { localStorage.setItem(REC_KEY, JSON.stringify(rec)); } catch { /* sin almacenamiento */ } }
    this.cb.onGameOver({ earned: this.earned, missions: this.stats2.delivered, rings: this.stats2.rings, perfect: this.stats2.perfect, best, newRecord, diff: this.diff, reason: 'Sin aviones de reserva' });
  }

  // ---------------- Bucle ----------------
  private loop(now: number) {
    this.raf = requestAnimationFrame(this.loop);
    const dt = Math.min(0.05, Math.max(0, (now - (this.last || now)) / 1000)); this.last = now; this.t += dt;
    if (this.mode === 'play') this.updatePlay(dt);
    else if (this.mode === 'rollout') this.updateRollout(dt);
    else if (this.mode === 'crash') { this.crashT += dt; if (this.crashT > 2.6) { if (this.lives <= 0) this.gameOver(); else this.respawn(); } }
    else if (this.mode === 'menu') this.updateMenu(dt);
    if (this.mode !== 'paused') {
      this.smoke.update(dt); this.sparks.update(dt);
      if (this.mission && this.mode !== 'hangar' && this.mode !== 'play') this.mission.update(dt, FAR, FAR, this.t);
    }
    this.updateVisuals(dt);
    this.renderer.render(this.scene, this.camera);
    if (this.ctx) drawOverlay(this.ctx, this.overlay.clientWidth || this.host.clientWidth, this.overlay.clientHeight || this.host.clientHeight, this);
    this.hudT -= dt;
    if (this.hudT <= 0 && (this.mode === 'play' || this.mode === 'rollout' || this.mode === 'crash')) { this.hudT = 0.1; this.cb.onHud(this.hudData()); }
  }

  private updatePlay(dt: number) {
    const f = this.flight, m = this.mission!, D = DIFFS[this.diff];
    this.input.update(); this.prev.copy(f.pos);
    this.gustT -= dt; this.gust *= Math.exp(-0.7 * dt); this.windAng += dt * 0.02;
    if (this.gustT <= 0 && this.windStr > 2) {
      this.gustT = 7 + Math.random() * 9; this.gust = this.windStr * (0.6 + Math.random() * 0.8);
      f.roll += (Math.random() < 0.5 ? -1 : 1) * 0.35 * D.wind; this.sfx.gust(); this.cb.onMessage('¡Ráfaga de viento!', 'info');
    }
    this.wind.set(Math.sin(this.windAng), 0, Math.cos(this.windAng)).multiplyScalar(this.windStr + this.gust);
    this.storm = m.stormAt(f.pos);
    if (this.storm > 0) {
      this.wind.y += (Math.random() - 0.5) * 40 * this.storm; f.roll += (Math.random() - 0.5) * this.storm * 4 * dt;
      this.damage(this.storm * 13 * D.dmg * dt, null); this.shake = Math.max(this.shake, this.storm * 0.7);
    }
    f.update(dt, this.input.state, this.wind, this.stats, m.cargo.weight);
    // Límites del mapa y techo
    const lim = HALF - 700;
    if (Math.abs(f.pos.x) > lim || Math.abs(f.pos.z) > lim) {
      let d = Math.atan2(-f.pos.x, -f.pos.z) - f.heading; d = Math.atan2(Math.sin(d), Math.cos(d)); f.heading += d * dt * 0.9;
    }
    if (f.pos.y > 1500) f.pitch = Math.min(f.pitch, 0) - dt * 0.3;
    // Suelo, agua y pistas
    const gh = this.terrain.heightAt(f.pos.x, f.pos.z); this.agl = f.pos.y - GEAR - gh;
    if (gh < WATER && f.pos.y - 1 < WATER) { this.crash('¡Amerizaje forzoso!'); return; }
    if (this.agl <= 0) {
      const rw = this.terrain.runwayAt(f.pos.x, f.pos.z);
      if (!rw) { this.crash('¡Impacto contra el terreno!'); return; }
      if (!f.onGround) this.touchdown(rw);
      f.pos.y = gh + GEAR; f.pitch = Math.max(f.pitch, 0);
      if (f.speed < 42) f.pitch = Math.max(0, Math.min(f.pitch, 0.02));
    } else if (f.onGround && this.agl > 0.6) f.onGround = false;
    // Misión
    for (const e of m.update(dt, this.prev, f.pos, this.t)) this.onEvent(e);
    // Avisos
    const runwayNear = this.terrain.runwayAt(f.pos.x, f.pos.z, 120);
    this.warn = f.engineOut ? 'SIN COMBUSTIBLE · PLANEA' : (this.agl < 50 && f.vel.y < -6 && !runwayNear) ? '¡TERRENO! ¡SUBE!' : f.stall ? 'PÉRDIDA · BAJA EL MORRO'
      : this.storm > 0 ? 'TORMENTA' : f.fuel < this.stats.fuelCap * 0.2 ? 'COMBUSTIBLE BAJO' : null;
    if (this.warn && this.warn !== 'TORMENTA') this.sfx.warn(dt);
    this.sfx.setEngine(f.speed / 80, this.input.state.turbo, f.engineOut);
  }

  private onEvent(e: MissionEvent) {
    const m = this.mission!, f = this.flight, cap = this.stats;
    if (e.type === 'ring') {
      this.sfx.ring(m.streak); this.sparks.burst(e.pos, 36, 30, m.onFinal ? C.green : C.cyan, 5, 0.9);
      if (m.streak > 0 && m.streak % 5 === 0) this.cb.onMessage(`¡Racha de ${m.streak} anillos!`, 'good');
    } else if (e.type === 'gold') { this.sfx.gold(); this.sparks.burst(e.pos, 50, 34, C.gold, 6, 1.1); this.cb.onMessage('Anillo dorado +$60', 'gold'); }
    else if (e.type === 'miss') { this.sfx.miss(); this.cb.onMessage('Anillo fallado −$25', 'bad'); }
    else if (e.type === 'fuel') { f.fuel = Math.min(cap.fuelCap, f.fuel + cap.fuelCap * 0.35); this.sfx.pickup(); this.sparks.burst(e.pos, 30, 20, C.gold, 5, 0.8); this.cb.onMessage('+35 % combustible', 'good'); }
    else if (e.type === 'repair') { f.hull = Math.min(cap.hullCap, f.hull + cap.hullCap * 0.4); this.sfx.pickup(); this.sparks.burst(e.pos, 30, 20, C.green, 5, 0.8); this.cb.onMessage('Reparación de emergencia', 'good'); }
    else if (e.type === 'bird') { this.smoke.burst(e.pos, 14, 10, C.puff, 2.5, 1.2); this.damage(7 * DIFFS[this.diff].dmg, '¡Choque con aves!'); }
    else if (e.type === 'thunder') { this.sfx.thunder(); if (this.storm > 0) this.damage(6 * DIFFS[this.diff].dmg, '¡Rayo!'); }
  }

  private updateRollout(dt: number) {
    const f = this.flight, ap = this.mission!.to; this.rollT += dt;
    const sp = f.speed; f.update(dt, NO_INPUT, this.wind, this.stats, 1);
    let d = ap.dir - f.heading; d = Math.atan2(Math.sin(d), Math.cos(d)); if (Math.abs(d) > Math.PI / 2) d = Math.atan2(Math.sin(d + Math.PI), Math.cos(d + Math.PI));
    f.heading += d * Math.min(1, dt * 2); f.pitch *= 0.9; f.speed = Math.max(0, sp - 15 * dt);
    f.pos.y = this.terrain.heightAt(f.pos.x, f.pos.z) + GEAR; this.agl = 0; this.warn = null;
    this.sfx.setEngine(f.speed / 120, false, false);
    if (f.speed < 2 || this.rollT > 5) this.finishDelivery();
  }

  private updateMenu(dt: number) {
    const P = this.terrain.path, N = P.length; this.menuS = (this.menuS + dt * 2.4) % N;
    const i = Math.floor(this.menuS), a = P[i], b = P[(i + 1) % N], c = P[(i + 12) % N], u = this.menuS - i;
    const f = this.flight; f.pos.lerpVectors(a, b, u); f.pos.y += 95;
    const h = Math.atan2(c.x - f.pos.x, c.z - f.pos.z); let d = h - f.heading; d = Math.atan2(Math.sin(d), Math.cos(d));
    f.heading += d * Math.min(1, dt * 1.5); f.roll = clamp(-d * 2.2, -0.6, 0.6); f.pitch = 0.04; f.speed = 60;
    const cp = Math.cos(f.pitch); f.fwd.set(Math.sin(f.heading) * cp, Math.sin(f.pitch), Math.cos(f.heading) * cp);
  }

  private snapCamera() {
    const f = this.flight; this.camPos.set(f.pos.x - Math.sin(f.heading) * 30, f.pos.y + 9, f.pos.z - Math.cos(f.heading) * 30); this.camLook.copy(f.pos);
  }

  private updateVisuals(dt: number) {
    const f = this.flight, g = this.plane.group, cam = this.camera;
    g.position.copy(f.pos); g.rotation.set(-f.pitch, f.heading, f.roll);
    const spin = this.mode === 'hangar' || this.mode === 'over' || f.engineOut ? 0.4 : 45;
    this.plane.props.forEach(p => { p.rotation.z += dt * spin; });
    this.plane.strobe.visible = (this.t % 1.2) < 0.08;
    // Humo de motores, vapor en turbo, humo de daños
    this.emitT -= dt;
    if (this.emitT <= 0 && g.visible && (this.mode === 'play' || this.mode === 'menu')) {
      this.emitT = 0.045; const v = new THREE.Vector3(0, 1.5, 0);
      for (const s of [-1, 1]) {
        this.smoke.emit(g.localToWorld(new THREE.Vector3(s * 3.9, 1.3, -1.2)), v, C.exh, this.input.state.turbo ? 1.4 : 0.9, 0.7, 2.6);
        if (this.input.state.turbo && this.mode === 'play') this.sparks.emit(g.localToWorld(new THREE.Vector3(s * 10.6, 1.75, 0.5)), v.set(0, 0, 0), C.puff, 1.4, 0.7, 1);
      }
      if (f.hull < this.stats.hullCap * 0.4 && this.mode === 'play') this.smoke.emit(g.localToWorld(new THREE.Vector3(3.9, 1.6, -1.5)), new THREE.Vector3(0, 3, 0), C.smoke, 4, 2.2, 2.2);
    }
    // Sombra de contacto
    const gh = Math.max(this.terrain.heightAt(f.pos.x, f.pos.z), WATER);
    const alt = f.pos.y - gh; this.shadow.visible = g.visible && alt < 160;
    this.shadow.position.set(f.pos.x, gh + 0.7, f.pos.z); this.shadow.rotation.y = f.heading;
    (this.shadow.material as THREE.MeshBasicMaterial).opacity = clamp(1 - alt / 160, 0, 1);
    // Mangas de viento
    this.terrain.airports.forEach((ap, i) => {
      const s = this.airports.socks[i]; s.rotation.y = Math.atan2(-this.wind.x, -this.wind.z) - ap.dir + Math.sin(this.t * 3 + i) * 0.08;
      s.rotation.x = -(1 - Math.min(1, this.wind.length() / 9)) * 0.9;
    });
    // Cámara
    const k = 1 - Math.exp(-dt * (this.mode === 'play' ? 4.2 : 1.6)), des = new THREE.Vector3(), look = new THREE.Vector3();
    if (this.mode === 'menu') {
      const rx = -Math.cos(f.heading), rz = Math.sin(f.heading), sw = Math.sin(this.t * 0.25) * 5;
      des.set(f.pos.x - f.fwd.x * 26 - rx * (12 + sw), f.pos.y + 5 + sw * 0.4, f.pos.z - f.fwd.z * 26 - rz * (12 + sw));
      look.set(f.pos.x - rx * 15 + f.fwd.x * 12, f.pos.y + 3, f.pos.z - rz * 15 + f.fwd.z * 12);
      this.camPos.lerp(des, 0.2); this.camLook.lerp(look, 0.2);
    } else if (this.mode === 'hangar' || this.mode === 'over') {
      const a = this.t * 0.18 + 2.2;
      des.set(f.pos.x + Math.sin(a) * 42, f.pos.y + 12, f.pos.z + Math.cos(a) * 42); look.copy(f.pos);
    } else if (this.mode === 'crash') { des.copy(this.camPos); look.copy(f.pos); }
    else {
      des.set(f.pos.x - Math.sin(f.heading) * 27, f.pos.y + 8.5 - f.pitch * 8, f.pos.z - Math.cos(f.heading) * 27);
      look.copy(f.pos).addScaledVector(f.fwd, 26); look.y += 2.5;
    }
    this.camPos.lerp(des, k); this.camLook.lerp(look, Math.min(1, k * 1.6));
    this.camPos.y = Math.max(this.camPos.y, Math.max(this.terrain.heightAt(this.camPos.x, this.camPos.z), WATER) + 3);
    this.shake = Math.max(0, this.shake - dt * 1.5); this.dmgFlash = Math.max(0, this.dmgFlash - dt * 1.4);
    const sh = this.shake * this.shake * 1.2;
    cam.position.set(this.camPos.x + (Math.random() - 0.5) * sh, this.camPos.y + (Math.random() - 0.5) * sh, this.camPos.z + (Math.random() - 0.5) * sh);
    cam.lookAt(this.camLook);
    if (this.mode === 'play') cam.rotateZ(-f.roll * 0.22);
    const fov = 58 + clamp((f.speed - 60) * 0.18, 0, 14); if (Math.abs(cam.fov - fov) > 0.05) { cam.fov += (fov - cam.fov) * k; cam.updateProjectionMatrix(); }
    this.sky.position.copy(cam.position);
    const rel = this.wind.clone().sub(this.mode === 'play' ? f.vel : new THREE.Vector3());
    this.streaks.update(dt, cam.position, rel, this.windStr + this.gust); this.streaks.lines.visible = this.mode === 'play';
  }

  hudData(): HudData {
    const f = this.flight, m = this.mission!;
    const wr = Math.atan2(this.wind.x, this.wind.z) - f.heading;
    return {
      money: this.money, mission: m.index, cargo: m.cargo.name, dest: m.to.name, dist: Math.round(Math.hypot(m.to.x - f.pos.x, m.to.z - f.pos.z)),
      hits: m.hits, total: m.route.length, speed: Math.round(f.speed * 3.6), alt: Math.max(0, Math.round(this.agl)), vs: Math.round(f.vel.y * 10) / 10,
      fuel: f.fuel / this.stats.fuelCap, hull: Math.max(0, f.hull / this.stats.hullCap), cargoInt: Math.round(this.cargoInt), lives: this.lives,
      windRel: wr, windKmh: Math.round(Math.hypot(this.wind.x, this.wind.z) * 3.6), warn: this.warn, approach: m.onFinal,
      turbo: this.input.state.turbo, flaps: this.input.state.flaps, time: m.time, par: m.par,
    };
  }

  dispose() {
    cancelAnimationFrame(this.raf); this.ro.disconnect(); this.input.detach(); this.sfx.dispose();
    this.mission?.dispose(); this.pending?.dispose();
    this.terrain.dispose(); this.airports.dispose(); this.clouds.dispose(); this.plane.dispose(); this.smoke.dispose(); this.sparks.dispose(); this.streaks.dispose();
    this.sky.geometry.dispose(); (this.sky.material as THREE.Material).dispose();
    this.shadow.geometry.dispose(); const sm = this.shadow.material as THREE.MeshBasicMaterial; sm.map?.dispose(); sm.dispose();
    this.renderer.dispose(); this.renderer.domElement.remove();
  }
}

import * as THREE from 'three';
import type { InputState } from './input';
import { clamp } from './noise';

/** Modelo de vuelo arcade de un avión de carga: estable, pesado y con pérdida a baja velocidad. */
export type UpgradeId = 'motor' | 'tanque' | 'fuselaje' | 'bodega';
export type Upgrades = Record<UpgradeId, number>;
export const UPGRADES: Record<UpgradeId, { name: string; desc: string; cost: number[] }> = {
  motor: { name: 'Motores', desc: '+8 km/h de crucero y mejor ascenso', cost: [450, 900, 1600] },
  tanque: { name: 'Depósitos', desc: '+30 % de combustible', cost: [350, 750, 1300] },
  fuselaje: { name: 'Fuselaje', desc: '+30 % de resistencia', cost: [400, 850, 1500] },
  bodega: { name: 'Bodega', desc: '+15 % de pago por entrega', cost: [500, 1000, 1800] },
};

export interface Stats { cruise: number; turbo: number; flaps: number; fuelCap: number; hullCap: number; burn: number; climb: number }

export function statsFor(u: Upgrades, burn: number): Stats {
  const cruise = 64 + u.motor * 6;
  return { cruise, turbo: cruise + 32, flaps: 40, fuelCap: 100 * (1 + 0.3 * u.tanque), hullCap: 100 * (1 + 0.3 * u.fuselaje), burn, climb: 1 + u.motor * 0.12 };
}

export class Flight {
  pos = new THREE.Vector3();
  vel = new THREE.Vector3();
  fwd = new THREE.Vector3(0, 0, 1);
  heading = 0; pitch = 0; roll = 0; speed = 66;
  fuel = 100; hull = 100;
  stall = false; engineOut = false; onGround = false;

  reset(x: number, y: number, z: number, heading: number, speed: number) {
    this.pos.set(x, y, z); this.heading = heading; this.pitch = 0; this.roll = 0; this.speed = speed;
    this.stall = false; this.onGround = false; this.vel.set(0, 0, 0);
  }

  update(dt: number, inp: InputState, wind: THREE.Vector3, st: Stats, weight: number) {
    const g = this.onGround;
    if (inp.roll) this.roll += inp.roll * 1.7 * dt; else this.roll -= this.roll * Math.min(1, 2.3 * dt);
    this.roll = clamp(this.roll, g ? -0.05 : -1.0, g ? 0.05 : 1.0);
    if (inp.pitch) this.pitch += inp.pitch * 0.8 * dt * (inp.pitch > 0 ? st.climb / weight : 1);
    else this.pitch -= this.pitch * Math.min(1, 0.55 * dt);
    this.pitch = clamp(this.pitch, -0.62, 0.48);
    this.heading -= (Math.sin(this.roll) * 0.95 + (g ? inp.roll * 0.25 : inp.roll * 0.1)) * dt;

    this.engineOut = this.fuel <= 0;
    let target = st.cruise, burnK = 1;
    if (inp.turbo) { target = st.turbo; burnK = 2.3; } else if (inp.flaps) { target = st.flaps; burnK = 0.6; }
    if (this.engineOut) target = 0;
    const thrust = (target - this.speed) * (this.engineOut ? 0.04 : inp.flaps ? 0.7 : 0.45);
    this.speed += (thrust - 9.8 * Math.sin(this.pitch) * 0.62 * weight) * dt;
    if (g && inp.flaps) this.speed -= 14 * dt;
    this.speed = clamp(this.speed, 0, 175);

    const stallV = inp.flaps ? 29 : 35;
    this.stall = !g && this.speed < stallV;
    if (this.stall) this.pitch -= 0.7 * dt;
    const cp = Math.cos(this.pitch);
    this.fwd.set(Math.sin(this.heading) * cp, Math.sin(this.pitch), Math.cos(this.heading) * cp);
    this.vel.copy(this.fwd).multiplyScalar(this.speed);
    if (!g) {
      this.vel.add(wind);
      if (this.stall) this.vel.y -= (stallV - this.speed) * 1.1;
      if (this.engineOut) this.vel.y -= 2.5;
    }
    this.pos.addScaledVector(this.vel, dt);
    if (!this.engineOut && !g) this.fuel = Math.max(0, this.fuel - st.burn * burnK * dt);
  }
}

import * as THREE from 'three';
import { HALF } from './terrain';
import type { Game } from './engine';

/** Capa 2D sobre el 3D: marcador de objetivo, minimapa orientado al rumbo, PAPI y viñetas de daño. */
const v = new THREE.Vector3();

export function drawOverlay(g: CanvasRenderingContext2D, w: number, h: number, game: Game) {
  g.clearRect(0, 0, w, h);
  const m = game.mission, mode = game.mode;
  if (game.dmgFlash > 0.01) vignette(g, w, h, `rgba(220,40,30,${game.dmgFlash * 0.45})`);
  if (game.storm > 0.01 && mode === 'play') vignette(g, w, h, `rgba(40,50,70,${game.storm * 0.55})`);
  if (!m || (mode !== 'play' && mode !== 'rollout' && mode !== 'crash')) return;
  const f = game.flight, small = w < 640;

  // --- Marcador del objetivo ---
  const tgt = m.target, isRwy = m.next >= m.route.length;
  const dist = Math.round(tgt.distanceTo(f.pos));
  v.copy(tgt).project(game.camera);
  const behind = v.z > 1, sx = (v.x * 0.5 + 0.5) * w, sy = (-v.y * 0.5 + 0.5) * h;
  const color = isRwy ? '#ffb340' : m.route[m.next].kind === 'approach' ? '#4dff8a' : '#29d3ff';
  const label = isRwy ? `PISTA ${m.to.name.toUpperCase()}` : `${dist} m`;
  g.font = '600 12px ui-monospace, SFMono-Regular, Menlo, monospace'; g.textAlign = 'center';
  if (!behind && sx > 40 && sx < w - 40 && sy > 40 && sy < h - 40) {
    const s = 14 + Math.sin(game.t * 6) * 2;
    g.strokeStyle = color; g.lineWidth = 2; g.shadowColor = 'rgba(0,0,0,0.5)'; g.shadowBlur = 4;
    g.beginPath(); g.moveTo(sx, sy - s); g.lineTo(sx + s, sy); g.lineTo(sx, sy + s); g.lineTo(sx - s, sy); g.closePath(); g.stroke();
    g.lineWidth = 3; g.strokeStyle = 'rgba(12,24,48,0.8)'; g.strokeText(label, sx, sy + s + 16); g.fillStyle = color; g.fillText(label, sx, sy + s + 16); g.shadowBlur = 0;
  } else {
    let ax = v.x, ay = -v.y; if (behind) { ax = -ax; ay = -ay; }
    const a = Math.atan2(ay, ax), ex = w / 2 + Math.cos(a) * (w / 2 - 50), ey = h / 2 + Math.sin(a) * (h / 2 - 60);
    g.save(); g.translate(ex, ey); g.rotate(a); g.fillStyle = color; g.shadowColor = 'rgba(0,0,0,0.5)'; g.shadowBlur = 6;
    g.beginPath(); g.moveTo(18, 0); g.lineTo(-8, -11); g.lineTo(-3, 0); g.lineTo(-8, 11); g.closePath(); g.fill(); g.restore();
    g.lineWidth = 3; g.strokeStyle = 'rgba(12,24,48,0.8)'; g.strokeText(label, ex, ey + 26); g.fillStyle = color; g.fillText(label, ex, ey + 26);
  }

  // --- PAPI: luces de senda de planeo en la aproximación final ---
  if (m.onFinal && mode === 'play') {
    const ap = m.to, d = (f.pos.x - ap.x) * -ap.fx + (f.pos.z - ap.z) * -ap.fz - ap.len / 2;
    if (d > -ap.len / 2) {
      const err = f.pos.y - (ap.h + 9 + Math.max(0, d) * 0.068), whites = err > 14 ? 4 : err > 5 ? 3 : err > -5 ? 2 : err > -14 ? 1 : 0;
      const x0 = w / 2 - 54, y0 = small ? 92 : 120;
      g.fillStyle = 'rgba(12,24,48,0.55)'; round(g, x0 - 14, y0 - 16, 136, 46, 10); g.fill();
      for (let i = 0; i < 4; i++) {
        g.beginPath(); g.arc(x0 + i * 36, y0, 8, 0, Math.PI * 2);
        g.fillStyle = i < whites ? '#ffffff' : '#ff3b30'; g.shadowColor = g.fillStyle; g.shadowBlur = 12; g.fill();
      }
      g.shadowBlur = 0; g.fillStyle = '#e8f2ff'; g.font = '600 10px ui-monospace, monospace';
      g.fillText(whites > 2 ? 'ALTO' : whites < 2 ? 'BAJO' : 'EN SENDA', w / 2, y0 + 23);
    }
  }

  // --- Minimapa (rumbo arriba) ---
  const S = small ? 112 : 150, cx = w - S / 2 - 16, cy = (small ? 60 : 70) + S / 2, R = 1700, k = S / 2 / R;
  g.save(); g.beginPath(); g.arc(cx, cy, S / 2, 0, Math.PI * 2); g.clip();
  g.fillStyle = '#2d5a78'; g.fillRect(cx - S / 2, cy - S / 2, S, S);
  g.translate(cx, cy); g.rotate(f.heading + Math.PI); g.scale(k, k); g.translate(-f.pos.x, -f.pos.z);
  g.globalAlpha = 0.95; g.drawImage(game.terrain.mapCanvas, -HALF, -HALF, HALF * 2, HALF * 2); g.globalAlpha = 1;
  g.lineWidth = 1.2 / k;
  m.route.forEach((r, i) => {
    if (r.state) return;
    g.fillStyle = i === m.next ? '#29d3ff' : r.kind === 'approach' ? '#4dff8a' : 'rgba(255,255,255,0.85)';
    g.beginPath(); g.arc(r.pos.x, r.pos.z, (i === m.next ? 4 : 2.4) / k, 0, Math.PI * 2); g.fill();
  });
  const ap = m.to; g.strokeStyle = '#ffb340'; g.lineWidth = 5 / k;
  g.beginPath(); g.moveTo(ap.x - ap.fx * ap.len / 2, ap.z - ap.fz * ap.len / 2); g.lineTo(ap.x + ap.fx * ap.len / 2, ap.z + ap.fz * ap.len / 2); g.stroke();
  g.restore();
  g.strokeStyle = 'rgba(255,255,255,0.9)'; g.lineWidth = 2; g.beginPath(); g.arc(cx, cy, S / 2, 0, Math.PI * 2); g.stroke();
  g.fillStyle = '#ffb340'; g.strokeStyle = '#14213d'; g.lineWidth = 1.5;
  g.beginPath(); g.moveTo(cx, cy - 8); g.lineTo(cx + 6, cy + 6); g.lineTo(cx, cy + 3); g.lineTo(cx - 6, cy + 6); g.closePath(); g.fill(); g.stroke();
}

function vignette(g: CanvasRenderingContext2D, w: number, h: number, c: string) {
  const gr = g.createRadialGradient(w / 2, h / 2, Math.min(w, h) * 0.3, w / 2, h / 2, Math.max(w, h) * 0.7);
  gr.addColorStop(0, 'rgba(0,0,0,0)'); gr.addColorStop(1, c); g.fillStyle = gr; g.fillRect(0, 0, w, h);
}

function round(g: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, r: number) {
  g.beginPath(); g.moveTo(x + r, y); g.arcTo(x + w, y, x + w, y + h, r); g.arcTo(x + w, y + h, x, y + h, r); g.arcTo(x, y + h, x, y, r); g.arcTo(x, y, x + w, y, r); g.closePath();
}

/** Entrada unificada: teclado (flechas/WASD) + joystick y botones táctiles. */
export interface InputState { pitch: number; roll: number; turbo: boolean; flaps: boolean }

export class Input {
  state: InputState = { pitch: 0, roll: 0, turbo: false, flaps: false };
  touch = { pitch: 0, roll: 0, turbo: false, flaps: false, active: false };
  invert = false;
  onPause: (() => void) | null = null;
  onAnyKey: (() => void) | null = null;
  private keys = new Set<string>();

  private down = (e: KeyboardEvent) => {
    const k = e.code;
    if (['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'Space'].includes(k)) e.preventDefault();
    this.onAnyKey?.();
    if ((k === 'Escape' || k === 'KeyP') && !e.repeat) { this.onPause?.(); return; }
    this.keys.add(k);
  };
  private up = (e: KeyboardEvent) => { this.keys.delete(e.code); };
  private blur = () => { this.keys.clear(); };

  attach() {
    window.addEventListener('keydown', this.down);
    window.addEventListener('keyup', this.up);
    window.addEventListener('blur', this.blur);
  }
  detach() {
    window.removeEventListener('keydown', this.down);
    window.removeEventListener('keyup', this.up);
    window.removeEventListener('blur', this.blur);
  }

  /** Recalcula los ejes; una vez por fotograma. ↑ = subir (o bajar si está invertido). */
  update() {
    const k = this.keys; let p = 0, r = 0;
    if (k.has('ArrowUp') || k.has('KeyW')) p += 1;
    if (k.has('ArrowDown') || k.has('KeyS')) p -= 1;
    if (k.has('ArrowLeft') || k.has('KeyA')) r -= 1;
    if (k.has('ArrowRight') || k.has('KeyD')) r += 1;
    if (this.touch.active) { p += this.touch.pitch; r += this.touch.roll; }
    if (this.invert) p = -p;
    this.state.pitch = Math.max(-1, Math.min(1, p));
    this.state.roll = Math.max(-1, Math.min(1, r));
    this.state.turbo = k.has('ShiftLeft') || k.has('ShiftRight') || this.touch.turbo;
    this.state.flaps = k.has('Space') || k.has('KeyF') || this.touch.flaps;
  }

  reset() {
    this.keys.clear();
    this.state = { pitch: 0, roll: 0, turbo: false, flaps: false };
    Object.assign(this.touch, { pitch: 0, roll: 0, turbo: false, flaps: false, active: false });
  }
}

import * as THREE from 'three';
import { col } from './three-compat';
import { rng } from './noise';
import { cloudTex, radialTex } from './props';
import type { Airport, Terrain } from './terrain';

/** Misiones de entrega: anillos de ruta y aproximación, globos de suministro, tormentas y bandadas. */
export type DiffId = 'novato' | 'comercial' | 'veterano';
export const DIFFS: Record<DiffId, { label: string; sub: string; wind: number; burn: number; hazard: number; dmg: number; ring: number; land: number }> = {
  novato: { label: 'Novato', sub: 'Brisa suave, anillos amplios', wind: 0.55, burn: 0.85, hazard: 0.6, dmg: 0.6, ring: 1.25, land: 1.35 },
  comercial: { label: 'Comercial', sub: 'El oficio de verdad', wind: 1, burn: 1.1, hazard: 1, dmg: 1, ring: 1, land: 1 },
  veterano: { label: 'Veterano', sub: 'Ráfagas y tormentas', wind: 1.5, burn: 1.35, hazard: 1.45, dmg: 1.35, ring: 0.85, land: 0.8 },
};

export interface Cargo { name: string; pay: number; weight: number; fragile: number }
export const CARGOS: Cargo[] = [
  { name: 'Correo urgente', pay: 1, weight: 0.9, fragile: 0.6 },
  { name: 'Medicinas', pay: 1.3, weight: 0.9, fragile: 1.6 },
  { name: 'Víveres', pay: 1.05, weight: 1.1, fragile: 0.8 },
  { name: 'Equipo minero', pay: 1.4, weight: 1.3, fragile: 0.5 },
  { name: 'Instrumental científico', pay: 1.6, weight: 1, fragile: 2 },
];

export type RingKind = 'route' | 'gold' | 'approach';
export interface Ring { kind: RingKind; pos: THREE.Vector3; n: THREE.Vector3; r: number; mesh: THREE.Mesh; mat: THREE.MeshBasicMaterial; halo: THREE.MeshBasicMaterial; state: 0 | 1 | 2; fade: number }
interface Pickup { kind: 'fuel' | 'repair'; pos: THREE.Vector3; obj: THREE.Group; taken: boolean; ph: number }
interface Storm { pos: THREE.Vector3; r: number; flash: THREE.SpriteMaterial; t: number }
interface Flock { c: THREE.Vector3; mesh: THREE.InstancedMesh; ph: number; alive: boolean[]; cd: number }
export interface MissionEvent { type: 'ring' | 'gold' | 'miss' | 'fuel' | 'repair' | 'bird' | 'thunder'; pos: THREE.Vector3 }

const RING_COL: Record<RingKind, string> = { route: '#29d3ff', gold: '#ffc533', approach: '#4dff8a' };
let shared: { torus: THREE.TorusGeometry; halo: THREE.PlaneGeometry; haloTex: THREE.Texture; cloud: THREE.Texture; flash: THREE.Texture; bird: THREE.BufferGeometry } | null = null;
function assets() {
  if (shared) return shared;
  const bird = new THREE.BufferGeometry();
  bird.setAttribute('position', new THREE.BufferAttribute(new Float32Array([0, 0, 0.7, -2.4, 0.7, -0.3, 0, 0, -0.7, 0, 0, 0.7, 0, 0, -0.7, 2.4, 0.7, -0.3]), 3));
  bird.computeVertexNormals();
  shared = {
    torus: new THREE.TorusGeometry(1, 0.075, 8, 44), halo: new THREE.PlaneGeometry(2.7, 2.7),
    haloTex: radialTex([[0, 'rgba(255,255,255,0)'], [0.62, 'rgba(255,255,255,0)'], [0.72, 'rgba(255,255,255,0.75)'], [0.8, 'rgba(255,255,255,0.12)'], [1, 'rgba(255,255,255,0)']], 128),
    cloud: cloudTex(), flash: radialTex([[0, 'rgba(230,240,255,1)'], [1, 'rgba(230,240,255,0)']], 64), bird,
  };
  return shared;
}

export class Mission {
  group = new THREE.Group();
  route: Ring[] = []; golds: Ring[] = [];
  pickups: Pickup[] = []; storms: Storm[] = []; flocks: Flock[] = [];
  next = 0; hits = 0; misses = 0; goldCash = 0; streak = 0; time = 0;
  from: Airport; to: Airport; cargo: Cargo; distance = 0; par = 0; legs: number;
  private own: Array<{ dispose(): void }> = [];

  constructor(t: Terrain, public index: number, fromIdx: number, diff: DiffId, seed: number) {
    const D = DIFFS[diff], R = rng(seed * 97 + index * 13), N = t.path.length;
    this.legs = index >= 4 && index % 2 === 0 ? 2 : 1;
    this.from = t.airports[fromIdx]; this.to = t.airports[(fromIdx + this.legs) % t.airports.length];
    this.cargo = index === 1 ? CARGOS[0] : CARGOS[Math.floor(R() * CARGOS.length)];
    const i0 = this.from.pathIndex + 18; let i1 = this.to.pathIndex - 40; while (i1 <= i0) i1 += N;
    this.distance = (i1 - i0 + 58) * 25;
    const rr = Math.max(9, 15.5 - index * 0.45) * D.ring;
    const tan = new THREE.Vector3(), side = new THREE.Vector3();
    let k = 0;
    for (let i = i0 + 4; i <= i1; i += 9, k++) {
      const p = t.path[i % N]; t.pathTangent(i % N, tan); side.set(tan.z, 0, -tan.x);
      const off = Math.sin(k * 1.3 + seed) * Math.min(22, 6 + index * 2.5);
      const pos = p.clone().addScaledVector(side, off);
      pos.y = Math.max(p.y + 48 + Math.sin(k * 0.7 + seed) * (14 + index * 2), t.heightAt(pos.x, pos.z) + rr + 14);
      this.route.push(this.ring('route', pos, tan, rr));
      if (k % 4 === 2) {
        const gp = t.path[(i + 4) % N].clone().addScaledVector(side, (k % 8 === 2 ? 1 : -1) * 42);
        gp.y = Math.max(pos.y + (R() - 0.3) * 30, t.heightAt(gp.x, gp.z) + 22);
        this.golds.push(this.ring('gold', gp, tan, rr * 0.75));
      }
      if (k % 6 === 4 || (k % 11 === 8 && index > 1)) this.pickup(k % 6 === 4 ? 'fuel' : 'repair', t.path[(i + 5) % N].clone().addScaledVector(side, -off * 0.5).setY(pos.y + 6));
    }
    // Aproximación final alineada con la pista (senda de planeo)
    const ap = this.to, f = new THREE.Vector3(ap.fx, 0, ap.fz);
    const thr = new THREE.Vector3(ap.x, ap.h, ap.z).addScaledVector(f, -ap.len / 2);
    for (const d of [720, 520, 330, 160]) {
      const p = thr.clone().addScaledVector(f, -d); p.y = ap.h + 9 + d * 0.068;
      this.route.push(this.ring('approach', p, f, rr * 0.95));
    }
    this.par = this.distance / 62 + 12;
    // Peligros
    const nStorm = index >= 2 ? Math.min(4, Math.round((index / 2) * D.hazard)) : 0;
    for (let s = 0; s < nStorm; s++) {
      const r = this.route[2 + Math.floor(R() * Math.max(1, this.route.length - 7))];
      this.storm(r.pos.clone().add(new THREE.Vector3((R() - 0.5) * 50, (R() - 0.5) * 20, (R() - 0.5) * 50)));
    }
    const nFlock = Math.min(5, 1 + Math.floor(((index - 1) / 2) * D.hazard));
    for (let s = 0; s < nFlock; s++) {
      const r = this.route[Math.min(this.route.length - 5, 1 + Math.floor(R() * (this.route.length - 5)))];
      this.flock(r.pos.clone().add(new THREE.Vector3((R() - 0.5) * 60, 8 + R() * 18, (R() - 0.5) * 60)));
    }
    // Faro sobre la pista de destino
    const bm = new THREE.MeshBasicMaterial({ color: col('#ffb340'), transparent: true, opacity: 0.16, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide });
    const bg = new THREE.CylinderGeometry(8, 14, 600, 16, 1, true);
    const beam = new THREE.Mesh(bg, bm); beam.position.set(ap.x, ap.h + 300, ap.z); this.group.add(beam); this.own.push(bm, bg);
  }

  private ring(kind: RingKind, pos: THREE.Vector3, n: THREE.Vector3, r: number): Ring {
    const A = assets();
    const mat = new THREE.MeshBasicMaterial({ color: col(RING_COL[kind]), transparent: true });
    const halo = new THREE.MeshBasicMaterial({ map: A.haloTex, color: col(RING_COL[kind]), transparent: true, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide });
    const mesh = new THREE.Mesh(A.torus, mat); mesh.add(new THREE.Mesh(A.halo, halo));
    mesh.position.copy(pos); mesh.scale.setScalar(r); mesh.lookAt(pos.clone().add(n));
    this.group.add(mesh); this.own.push(mat, halo);
    return { kind, pos, n: n.clone(), r, mesh, mat, halo, state: 0, fade: 0 };
  }

  private pickup(kind: 'fuel' | 'repair', pos: THREE.Vector3) {
    const obj = new THREE.Group(); obj.position.copy(pos);
    const bal = new THREE.MeshPhongMaterial({ color: col(kind === 'fuel' ? '#e8412f' : '#f4f4f4'), shininess: 70, specular: col('#ffffff') });
    const crate = new THREE.MeshPhongMaterial({ color: col(kind === 'fuel' ? '#f2b21b' : '#2fbf5a'), flatShading: true });
    const sg = new THREE.SphereGeometry(4, 14, 10), cg = new THREE.ConeGeometry(1.1, 2.2, 8), bx = new THREE.BoxGeometry(3, 2.4, 3);
    const b = new THREE.Mesh(sg, bal); b.scale.set(1, 1.15, 1); b.position.y = 6; obj.add(b);
    const c = new THREE.Mesh(cg, bal); c.rotation.x = Math.PI; c.position.y = 1.9; obj.add(c);
    obj.add(new THREE.Mesh(bx, crate));
    this.group.add(obj); this.own.push(bal, crate, sg, cg, bx);
    this.pickups.push({ kind, pos, obj, taken: false, ph: Math.random() * 6 });
  }

  private storm(pos: THREE.Vector3) {
    const A = assets(), g = new THREE.Group(); g.position.copy(pos);
    const m = new THREE.SpriteMaterial({ map: A.cloud, color: col('#7b8494'), transparent: true, depthWrite: false, opacity: 0.95 });
    const flash = new THREE.SpriteMaterial({ map: A.flash, color: 0xdde8ff, transparent: true, blending: THREE.AdditiveBlending, depthWrite: false, opacity: 0 });
    for (let i = 0; i < 10; i++) {
      const s = new THREE.Sprite(m); const z = 70 + Math.random() * 60;
      s.position.set((Math.random() - 0.5) * 90, (Math.random() - 0.4) * 50, (Math.random() - 0.5) * 90); s.scale.set(z, z * 0.75, 1); g.add(s);
    }
    const f = new THREE.Sprite(flash); f.scale.setScalar(170); g.add(f);
    this.group.add(g); this.own.push(m, flash);
    this.storms.push({ pos, r: 62, flash, t: 1 + Math.random() * 3 });
  }

  private flock(c: THREE.Vector3) {
    const A = assets(), m = new THREE.MeshBasicMaterial({ color: col('#2b2f3a'), side: THREE.DoubleSide });
    const mesh = new THREE.InstancedMesh(A.bird, m, 11); mesh.frustumCulled = false;
    this.group.add(mesh); this.own.push(m);
    this.flocks.push({ c, mesh, ph: Math.random() * 6, alive: new Array(11).fill(true), cd: 0 });
  }

  /** Siguiente objetivo: anillo pendiente o la pista. */
  get target() { return this.next < this.route.length ? this.route[this.next].pos : new THREE.Vector3(this.to.x, this.to.h, this.to.z); }
  get onFinal() { return this.next >= this.route.length - 4; }

  private crossing(r: Ring, a: THREE.Vector3, b: THREE.Vector3) {
    const d0 = r.n.dot(new THREE.Vector3().subVectors(a, r.pos)), d1 = r.n.dot(new THREE.Vector3().subVectors(b, r.pos));
    if (!(d0 < 0 && d1 >= 0)) return -1;
    const p = a.clone().lerp(b, d0 / (d0 - d1));
    return p.distanceTo(r.pos);
  }

  update(dt: number, prev: THREE.Vector3, pos: THREE.Vector3, time: number): MissionEvent[] {
    const ev: MissionEvent[] = []; this.time += dt;
    for (let j = this.next; j < Math.min(this.route.length, this.next + 3); j++) {
      const r = this.route[j], d = this.crossing(r, prev, pos);
      if (d < 0 || d > r.r * 6) continue;
      for (let m = this.next; m < j; m++) { this.route[m].state = 2; this.misses++; ev.push({ type: 'miss', pos: this.route[m].pos }); }
      if (d < r.r * 1.12) { r.state = 1; this.hits++; this.streak++; ev.push({ type: 'ring', pos: r.pos }); }
      else { r.state = 2; this.misses++; this.streak = 0; ev.push({ type: 'miss', pos: r.pos }); }
      this.next = j + 1; break;
    }
    for (const g of this.golds) if (g.state === 0) {
      const d = this.crossing(g, prev, pos);
      if (d >= 0 && d < g.r * 1.15) { g.state = 1; this.goldCash += 60; ev.push({ type: 'gold', pos: g.pos }); }
    }
    const pulse = 1 + Math.sin(time * 5) * 0.06;
    [...this.route, ...this.golds].forEach((r, idx) => {
      if (r.state) {
        r.fade += dt * 2;
        if (r.state === 2) r.mat.color.copy(col('#ff4d4d')), r.halo.color.copy(col('#ff4d4d'));
        r.mesh.scale.setScalar(r.r * (1 + r.fade * (r.state === 1 ? 0.8 : 0.1)));
        r.mat.opacity = r.halo.opacity = Math.max(0, 1 - r.fade); r.mesh.visible = r.fade < 1;
        return;
      }
      const isNext = idx === this.next || r.kind === 'gold';
      r.mat.opacity = isNext ? 1 : 0.45; r.halo.opacity = isNext ? 0.9 : 0.2;
      r.mesh.scale.setScalar(r.r * (idx === this.next ? pulse : 1));
    });
    for (const p of this.pickups) {
      if (p.taken) { p.obj.scale.multiplyScalar(Math.max(0, 1 - dt * 5)); continue; }
      p.ph += dt; p.obj.position.y = p.pos.y + Math.sin(p.ph * 1.5) * 1.5; p.obj.rotation.y += dt * 0.6;
      if (p.obj.position.distanceTo(pos) < 13) { p.taken = true; ev.push({ type: p.kind, pos: p.obj.position }); }
    }
    for (const s of this.storms) {
      s.t -= dt; s.flash.opacity = Math.max(0, s.flash.opacity - dt * 3);
      if (s.t <= 0) { s.t = 1.5 + Math.random() * 3.5; s.flash.opacity = 1; if (s.pos.distanceTo(pos) < 500) ev.push({ type: 'thunder', pos: s.pos }); }
    }
    const m4 = new THREE.Matrix4(), q = new THREE.Quaternion(), e = new THREE.Euler(), sc = new THREE.Vector3(), bp = new THREE.Vector3();
    for (const f of this.flocks) {
      f.ph += dt * 0.5; f.cd -= dt;
      const near = f.c.distanceTo(pos) < 60;
      for (let i = 0; i < f.alive.length; i++) {
        const a = f.ph + i * 0.57, rad = 16 + (i % 4) * 6;
        bp.set(f.c.x + Math.cos(a) * rad, f.c.y + Math.sin(a * 2 + i) * 4, f.c.z + Math.sin(a) * rad);
        sc.set(1, f.alive[i] ? Math.sin(time * 9 + i * 1.7) : 0, 1);
        m4.compose(bp, q.setFromEuler(e.set(0, -a, 0)), sc); f.mesh.setMatrixAt(i, m4);
        if (near && f.alive[i] && f.cd <= 0 && bp.distanceTo(pos) < 8) { f.alive[i] = false; f.cd = 0.6; ev.push({ type: 'bird', pos: bp.clone() }); }
      }
      f.mesh.instanceMatrix.needsUpdate = true;
    }
    return ev;
  }

  /** Intensidad de tormenta (0..1) en un punto. */
  stormAt(p: THREE.Vector3) {
    let v = 0; for (const s of this.storms) v = Math.max(v, 1 - p.distanceTo(s.pos) / s.r);
    return v;
  }

  dispose() { this.own.forEach(o => o.dispose()); this.group.parent?.remove(this.group); }
}

/** Ruido de valor 2D determinista + fbm/ridged y un generador pseudoaleatorio con semilla. */
function hash(x: number, y: number, s: number) {
  let h = Math.imul(x, 374761393) + Math.imul(y, 668265263) + Math.imul(s, 982451653);
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  return ((h ^ (h >>> 16)) >>> 0) / 4294967295;
}

export function vnoise(x: number, y: number, s = 0) {
  const xi = Math.floor(x), yi = Math.floor(y), xf = x - xi, yf = y - yi;
  const u = xf * xf * (3 - 2 * xf), v = yf * yf * (3 - 2 * yf);
  const a = hash(xi, yi, s), b = hash(xi + 1, yi, s), c = hash(xi, yi + 1, s), d = hash(xi + 1, yi + 1, s);
  return a + (b - a) * u + (c - a) * v + (a - b - c + d) * u * v;
}

export function fbm(x: number, y: number, oct = 4, s = 0) {
  let sum = 0, amp = 0.5, f = 1, n = 0;
  for (let i = 0; i < oct; i++) { sum += amp * vnoise(x * f, y * f, s + i * 17); n += amp; amp *= 0.5; f *= 2.03; }
  return sum / n;
}

/** Ruido "crestas": picos afilados, ideal para cordilleras. */
export function ridged(x: number, y: number, oct = 5, s = 0) {
  let sum = 0, amp = 0.5, f = 1, n = 0, w = 1;
  for (let i = 0; i < oct; i++) {
    let v = 1 - Math.abs(vnoise(x * f, y * f, s + i * 31) * 2 - 1);
    v *= v * w; w = Math.min(1, v * 1.6);
    sum += amp * v; n += amp; amp *= 0.5; f *= 2.1;
  }
  return sum / n;
}

export function rng(seed: number) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export const clamp = (v: number, a: number, b: number) => (v < a ? a : v > b ? b : v);
export const smooth = (a: number, b: number, x: number) => { const t = clamp((x - a) / (b - a), 0, 1); return t * t * (3 - 2 * t); };

import * as THREE from 'three';
import { col, srgbTexture } from './three-compat';
import { rng } from './noise';
import type { Airport, Terrain } from './terrain';

/** Modelos y decorados procedurales: cielo de mañana, nubes, niebla de valle, avión y aeródromos. */
export const SUN_DIR = new THREE.Vector3(-0.55, 0.42, 0.72).normalize();

function canvasTex(w: number, h: number, draw: (g: CanvasRenderingContext2D) => void) {
  const cv = document.createElement('canvas'); cv.width = w; cv.height = h;
  draw(cv.getContext('2d')!);
  return srgbTexture(new THREE.CanvasTexture(cv)) as THREE.CanvasTexture;
}

export function radialTex(stops: Array<[number, string]>, size = 128) {
  return canvasTex(size, size, g => {
    const gr = g.createRadialGradient(size / 2, size / 2, 0, size / 2, size / 2, size / 2);
    stops.forEach(([o, c]) => gr.addColorStop(o, c));
    g.fillStyle = gr; g.fillRect(0, 0, size, size);
  });
}

export function cloudTex() {
  const R = rng(5);
  return canvasTex(256, 256, g => {
    for (let i = 0; i < 26; i++) {
      const x = 50 + R() * 156, y = 90 + R() * 90 - (Math.abs(x - 128) < 50 ? 30 : 0), r = 30 + R() * 46;
      const gr = g.createRadialGradient(x, y, 0, x, y, r);
      const sh = 235 + Math.round(R() * 20) - (y > 150 ? 22 : 0);
      gr.addColorStop(0, `rgba(${sh},${sh},${Math.min(255, sh + 8)},0.55)`); gr.addColorStop(1, 'rgba(255,255,255,0)');
      g.fillStyle = gr; g.fillRect(0, 0, 256, 256);
    }
  });
}

export function buildSky() {
  const mat = new THREE.ShaderMaterial({
    side: THREE.BackSide, depthWrite: false, fog: false,
    uniforms: {
      top: { value: new THREE.Color('#2a63c4') }, mid: { value: new THREE.Color('#6fa8e6') },
      hor: { value: new THREE.Color('#dcebf4') }, sun: { value: new THREE.Color('#fff1d0') }, sunDir: { value: SUN_DIR },
    },
    vertexShader: 'varying vec3 vP; void main(){ vP = position; gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }',
    fragmentShader: `uniform vec3 top, mid, hor, sun, sunDir; varying vec3 vP;
      void main(){ vec3 d = normalize(vP); float h = d.y;
        vec3 c = mix(hor, mid, smoothstep(0.0, 0.22, h)); c = mix(c, top, smoothstep(0.2, 0.85, h));
        c = mix(c, hor * 0.96, smoothstep(0.0, -0.1, h));
        float s = max(dot(d, sunDir), 0.0);
        c += sun * (pow(s, 1400.0) * 2.0 + pow(s, 60.0) * 0.22 + pow(s, 6.0) * 0.1);
        gl_FragColor = vec4(c, 1.0); }`,
  });
  const m = new THREE.Mesh(new THREE.SphereGeometry(9000, 32, 16), mat);
  m.renderOrder = -10; m.frustumCulled = false;
  return m;
}

/** Cúmulos altos y bancos de niebla matinal sobre los valles. */
export function buildClouds(t: Terrain) {
  const g = new THREE.Group(); const R = rng(21); const tex = cloudTex();
  const mat = new THREE.SpriteMaterial({ map: tex, transparent: true, depthWrite: false, fog: true });
  const mist = new THREE.SpriteMaterial({ map: tex, transparent: true, depthWrite: false, opacity: 0.42, fog: true });
  for (let i = 0; i < 34; i++) {
    const cx = (R() * 2 - 1) * 4300, cz = (R() * 2 - 1) * 4300, cy = 720 + R() * 380;
    for (let j = 0; j < 5; j++) {
      const s = new THREE.Sprite(mat); const sz = 180 + R() * 220;
      s.position.set(cx + (R() - 0.5) * 260, cy + (R() - 0.5) * 60, cz + (R() - 0.5) * 260); s.scale.set(sz, sz * 0.62, 1);
      g.add(s);
    }
  }
  for (let i = 0; i < t.path.length; i += 13) {
    const p = t.path[i]; if (R() < 0.35) continue;
    const s = new THREE.Sprite(mist); const sz = 160 + R() * 160;
    s.position.set(p.x + (R() - 0.5) * 120, p.y + 14 + R() * 10, p.z + (R() - 0.5) * 120); s.scale.set(sz * 1.6, sz * 0.35, 1);
    g.add(s);
  }
  return { group: g, dispose: () => { tex.dispose(); mat.dispose(); mist.dispose(); } };
}

const box = (w: number, h: number, d: number) => new THREE.BoxGeometry(w, h, d);
function add(parent: THREE.Object3D, geo: THREE.BufferGeometry, mat: THREE.Material, x: number, y: number, z: number, rx = 0, ry = 0, rz = 0) {
  const m = new THREE.Mesh(geo, mat); m.position.set(x, y, z); m.rotation.set(rx, ry, rz); parent.add(m); return m;
}

/** Avión de carga bimotor de ala alta (morro hacia +Z). */
export function buildPlane() {
  const g = new THREE.Group(); const own: Array<{ dispose(): void }> = [];
  const M = (c: string, o: THREE.MeshPhongMaterialParameters = {}) => { const m = new THREE.MeshPhongMaterial({ color: col(c), shininess: 40, specular: col('#555555'), flatShading: true, ...o }); own.push(m); return m; };
  const cream = M('#f3efe4'), amber = M('#f2a21b'), navy = M('#1c2f57'), dark = M('#222831'), glass = M('#20344f', { shininess: 120, specular: col('#ffffff') }), metal = M('#9aa3ad');
  const G = <T extends THREE.BufferGeometry>(x: T) => { own.push(x); return x; };
  const body = G(new THREE.CylinderGeometry(1.45, 1.5, 10, 10)); body.rotateX(Math.PI / 2);
  add(g, body, cream, 0, 0, 0.5).scale.set(1, 1.12, 1);
  const nose = G(new THREE.SphereGeometry(1.48, 10, 8)); add(g, nose, cream, 0, -0.05, 5.5).scale.set(1, 1.1, 1.25);
  const tail = G(new THREE.CylinderGeometry(0.45, 1.48, 6, 10)); tail.rotateX(-Math.PI / 2);
  add(g, tail, cream, 0, 0.55, -7.3, 0.12);
  add(g, G(box(3.05, 0.35, 15.5)), navy, 0, -0.25, -0.5);
  add(g, G(box(3.1, 0.18, 14)), amber, 0, 0.25, 0);
  add(g, G(box(2.2, 0.55, 0.9)), glass, 0, 0.75, 6.1, -0.35);
  for (const s of [-1, 1]) add(g, G(box(0.1, 0.5, 1.6)), glass, s * 1.5, 0.6, 5.0);
  // Ala alta, puntas ámbar, montantes
  add(g, G(box(21, 0.38, 2.7)), cream, 0, 1.75, 1.0);
  for (const s of [-1, 1]) {
    add(g, G(box(1.6, 0.4, 2.75)), amber, s * 10.1, 1.75, 1.0);
    add(g, G(box(0.18, 2.6, 0.35)), metal, s * 3.0, 0.45, 1.0, 0, 0, s * 0.85);
    const nac = G(new THREE.CylinderGeometry(0.62, 0.5, 3.6, 8)); nac.rotateX(Math.PI / 2);
    add(g, nac, navy, s * 3.9, 1.35, 2.2);
    add(g, G(box(0.12, 0.12, 1.2)), metal, s * 3.9, 0.9, 0.2);
  }
  // Cola en T
  add(g, G(box(0.28, 3.4, 2.6)), amber, 0, 2.6, -9.0, -0.28);
  add(g, G(box(0.3, 0.9, 2.3)), navy, 0, 3.6, -9.4, -0.28);
  add(g, G(box(7.6, 0.25, 1.9)), cream, 0, 4.25, -9.95);
  // Tren fijo
  const wheel = G(new THREE.CylinderGeometry(0.58, 0.58, 0.45, 12)); wheel.rotateZ(Math.PI / 2);
  for (const [x, z] of [[-1.9, 0.3], [1.9, 0.3], [0, 4.6]]) {
    add(g, G(box(0.22, 1.5, 0.3)), metal, x * 0.85, -1.55, z, 0, 0, x * 0.25);
    add(g, wheel, dark, x, -1.87, z);
  }
  // Hélices: palas + disco borroso
  const props: THREE.Group[] = [];
  const blade = G(box(0.22, 3.6, 0.08)); const disc = G(new THREE.CircleGeometry(1.85, 24));
  const discM = new THREE.MeshBasicMaterial({ color: col('#20242c'), transparent: true, opacity: 0.18, side: THREE.DoubleSide, depthWrite: false }); own.push(discM);
  for (const s of [-1, 1]) {
    const pg = new THREE.Group(); pg.position.set(s * 3.9, 1.35, 4.1);
    for (let b = 0; b < 3; b++) add(pg, blade, dark, 0, 0, 0, 0, 0, (b * Math.PI * 2) / 3);
    add(pg, disc, discM, 0, 0, 0.05);
    add(pg, G(new THREE.ConeGeometry(0.42, 0.9, 8)), amber, 0, 0, 0.3, Math.PI / 2);
    g.add(pg); props.push(pg);
  }
  // Luces de navegación
  const glow = radialTex([[0, 'rgba(255,255,255,1)'], [0.25, 'rgba(255,255,255,0.6)'], [1, 'rgba(255,255,255,0)']], 64); own.push(glow);
  const navLight = (c: string, x: number, y: number, z: number, s: number) => {
    const m = new THREE.SpriteMaterial({ map: glow, color: c, blending: THREE.AdditiveBlending, depthWrite: false, transparent: true }); own.push(m);
    const sp = new THREE.Sprite(m); sp.position.set(x, y, z); sp.scale.setScalar(s); g.add(sp); return sp;
  };
  navLight('#ff3b3b', 10.9, 1.75, 1.0, 1.6); navLight('#3bff7a', -10.9, 1.75, 1.0, 1.6);
  const strobe = navLight('#ffffff', 0, 4.4, -10.6, 3);
  return { group: g, props, strobe, dispose: () => own.forEach(o => o.dispose()) };
}

function runwayTex() {
  return canvasTex(128, 1024, g => {
    g.fillStyle = '#4a4f55'; g.fillRect(0, 0, 128, 1024);
    for (let i = 0; i < 2600; i++) { g.fillStyle = `rgba(${Math.random() < 0.5 ? '0,0,0' : '255,255,255'},0.06)`; g.fillRect(Math.random() * 128, Math.random() * 1024, 2, 2); }
    g.fillStyle = '#f4f4ef'; g.fillRect(6, 0, 3, 1024); g.fillRect(119, 0, 3, 1024);
    for (let y = 120; y < 900; y += 46) g.fillRect(62, y, 4, 24);
    for (const y0 of [12, 962]) for (let x = 14; x < 114; x += 12) if (Math.abs(x + 3 - 64) > 8) g.fillRect(x, y0, 6, 50);
    for (const y0 of [150, 830]) { g.fillRect(30, y0, 12, 40); g.fillRect(86, y0, 12, 40); }
    g.fillStyle = '#f2a21b'; g.fillRect(0, 0, 128, 4); g.fillRect(0, 1020, 128, 4);
  });
}

/** Aeródromo de montaña: pista, luces, hangar, torre, depósitos y manga de viento. */
export function buildAirports(t: Terrain) {
  const root = new THREE.Group(); const own: Array<{ dispose(): void }> = [];
  const M = (c: string) => { const m = new THREE.MeshPhongMaterial({ color: col(c), flatShading: true, shininess: 10 }); own.push(m); return m; };
  const rTex = runwayTex(); own.push(rTex);
  const rMat = new THREE.MeshPhongMaterial({ map: rTex, shininess: 6 }); own.push(rMat);
  const red = M('#c8402f'), white = M('#eeeae0'), steel = M('#8d97a3'), roofM = M('#3f5c7a'), glass = M('#2b4a68'), orange = M('#ff7a1a'), apron = M('#9ea3a5');
  const lightM = new THREE.MeshBasicMaterial({ color: col('#ffd27a') }); own.push(lightM);
  const geos = {
    hangar: box(32, 11, 24), roof: new THREE.CylinderGeometry(12, 12, 32, 12, 1, false, 0, Math.PI), tower: new THREE.CylinderGeometry(2.4, 3, 18, 8),
    cab: new THREE.CylinderGeometry(4.2, 3.4, 4, 8), cap: new THREE.ConeGeometry(4.6, 2, 8), tank: new THREE.CylinderGeometry(4, 4, 7, 14),
    pole: new THREE.CylinderGeometry(0.2, 0.2, 9, 6), sock: new THREE.ConeGeometry(1, 5, 10, 1, true), lamp: box(0.8, 0.5, 0.8), apron: box(70, 0.5, 120), door: box(26, 9, 0.3),
  };
  Object.values(geos).forEach(x => own.push(x));
  geos.roof.rotateZ(Math.PI / 2); geos.sock.rotateX(-Math.PI / 2);
  const socks: THREE.Object3D[] = [];
  for (const ap of t.airports) {
    const a = new THREE.Group(); a.position.set(ap.x, ap.h, ap.z); a.rotation.y = ap.dir; root.add(a);
    const rg = new THREE.PlaneGeometry(ap.width, ap.len); rg.rotateX(-Math.PI / 2); own.push(rg);
    add(a, rg, rMat, 0, 0.35, 0);
    const n = Math.floor(ap.len / 30) + 1, lamps = new THREE.InstancedMesh(geos.lamp, lightM, n * 2), m4 = new THREE.Matrix4();
    for (let i = 0; i < n; i++) for (const s of [0, 1]) lamps.setMatrixAt(i * 2 + s, m4.makeTranslation((s ? 1 : -1) * (ap.width / 2 + 2), 0.5, -ap.len / 2 + i * 30));
    a.add(lamps);
    const side = ap.width / 2 + 52;
    add(a, geos.apron, apron, side - 4, 0.1, -20);
    add(a, geos.hangar, white, side + 8, 5.5, -40, 0, Math.PI / 2);
    add(a, geos.roof, roofM, side + 8, 11, -40, 0, Math.PI / 2);
    add(a, geos.door, roofM, side - 4.2, 4.6, -40, 0, Math.PI / 2);
    add(a, geos.tower, white, side, 9, 50);
    add(a, geos.cab, glass, side, 20, 50); add(a, geos.cap, red, side, 23, 50);
    add(a, geos.tank, white, side + 14, 3.5, 22); add(a, geos.tank, red, side + 24, 3.5, 22);
    add(a, geos.pole, steel, -ap.width / 2 - 16, 4.5, -ap.len / 2 + 50);
    const sock = new THREE.Group(); sock.position.set(-ap.width / 2 - 16, 8.6, -ap.len / 2 + 50); a.add(sock);
    add(sock, geos.sock, orange, 0, 0, -2.5); socks.push(sock);
  }
  return { group: root, socks, dispose: () => own.forEach(o => o.dispose()) };
}

import * as THREE from 'three';
import { col } from './three-compat';
import { clamp, fbm, ridged, rng, smooth, vnoise } from './noise';

/** Mundo: cordilleras con un circuito de valles que une 5 aeródromos de montaña. */
export const HALF = 4500;
const SEG = 225;
const NV = SEG + 1;
const CELL = (HALF * 2) / SEG;
export const WATER = 64;
export const GEAR = 2.45;

export interface Airport {
  id: number; name: string; x: number; z: number; h: number;
  dir: number; fx: number; fz: number; len: number; width: number; pathIndex: number;
}

const NAMES = ['Valle Alto', 'Halcón', 'Pinar Azul', 'El Mirador', 'Los Neveros'];

export class Terrain {
  path: THREE.Vector3[] = [];
  airports: Airport[] = [];
  heights = new Float32Array(NV * NV);
  group = new THREE.Group();
  mapCanvas: HTMLCanvasElement;
  private slope = new Float32Array(NV * NV);
  private rel = new Float32Array(NV * NV);
  private apw = new Float32Array(NV * NV);
  private owned: Array<{ dispose(): void }> = [];

  constructor(seed = 11) {
    const R = rng(seed);
    // --- 1. Ruta del valle: curva cerrada que pasa recta por cada aeródromo ---
    const ctrl: THREE.Vector3[] = []; const apCtrl: THREE.Vector3[] = []; const apDir: THREE.Vector3[] = [];
    const n = 5;
    for (let i = 0; i < n; i++) {
      const a = 0.5 + (i * Math.PI * 2) / n, r = 2650;
      const p = new THREE.Vector3(Math.cos(a) * r, 0, Math.sin(a) * r);
      const t = new THREE.Vector3(-Math.sin(a), 0, Math.cos(a));
      ctrl.push(p.clone().addScaledVector(t, -380), p, p.clone().addScaledVector(t, 380));
      apCtrl.push(p); apDir.push(t);
      for (const k of [0.36, 0.66]) {
        const b = a + (k * Math.PI * 2) / n, rr = r + (R() - 0.5) * 1300;
        ctrl.push(new THREE.Vector3(Math.cos(b) * rr, 0, Math.sin(b) * rr));
      }
    }
    const curve = new THREE.CatmullRomCurve3(ctrl, true, 'catmullrom', 0.5);
    this.path = curve.getSpacedPoints(Math.round(curve.getLength() / 25));
    this.path.pop();
    const N = this.path.length;
    for (const p of this.path) p.y = 52 + 95 * fbm(p.x * 0.00035 + 3, p.z * 0.00035, 3, seed);

    // --- 2. Aeródromos: suelo del valle aplanado a su altura ---
    apCtrl.forEach((p, i) => {
      let best = 0, bd = 1e12;
      this.path.forEach((q, j) => { const d = q.distanceToSquared(p); if (d < bd) { bd = d; best = j; } });
      const h = Math.max(this.path[best].y, WATER + 9);
      for (let j = -26; j <= 26; j++) {
        const q = this.path[(best + j + N) % N]; const w = smooth(26, 10, Math.abs(j));
        q.y = q.y + (h - q.y) * w;
      }
      const d = apDir[i];
      this.airports.push({ id: i, name: NAMES[i], x: p.x, z: p.z, h, dir: Math.atan2(d.x, d.z), fx: d.x, fz: d.z, len: 440, width: 34, pathIndex: best });
    });

    // --- 3. Campo de distancia al valle (rasterizado alrededor de la ruta) ---
    const dist = new Float32Array(NV * NV).fill(1e9); const floor = new Float32Array(NV * NV);
    const rc = Math.ceil(700 / CELL);
    this.path.forEach(p => {
      const gx = Math.round((p.x + HALF) / CELL), gz = Math.round((p.z + HALF) / CELL);
      for (let z = Math.max(0, gz - rc); z <= Math.min(SEG, gz + rc); z++)
        for (let x = Math.max(0, gx - rc); x <= Math.min(SEG, gx + rc); x++) {
          const k = z * NV + x, dx = -HALF + x * CELL - p.x, dz = -HALF + z * CELL - p.z;
          const d = Math.sqrt(dx * dx + dz * dz);
          if (d < dist[k]) { dist[k] = d; floor[k] = p.y; }
        }
    });

    // --- 4. Alturas ---
    const H = this.heights;
    for (let z = 0; z < NV; z++) for (let x = 0; x < NV; x++) {
      const k = z * NV + x, wx = -HALF + x * CELL, wz = -HALF + z * CELL;
      const fl = dist[k] < 1e8 ? floor[k] : 60 + 90 * fbm(wx * 0.00035 + 3, wz * 0.00035, 3, seed);
      const t = smooth(55, 440, Math.min(dist[k], 900));
      const m = 110 + Math.pow(ridged(wx * 0.00042 + 11, wz * 0.00042 - 7, 5, seed), 1.5) * 860 + fbm(wx * 0.0022, wz * 0.0022, 3, 5) * 90;
      let h = fl + (fbm(wx * 0.004, wz * 0.004, 2, 9) - 0.5) * 12 * (1 - t) + t * m * (0.5 + 0.5 * t);
      h += smooth(HALF - 1000, HALF, Math.max(Math.abs(wx), Math.abs(wz))) * 650;
      for (const ap of this.airports) {
        const dx = wx - ap.x, dz = wz - ap.z;
        if (dx * dx + dz * dz > 700 * 700) continue;
        const u = Math.abs(dx * ap.fx + dz * ap.fz) - (ap.len / 2 + 100), v = Math.abs(dx * ap.fz - dz * ap.fx) - (ap.width / 2 + 80);
        const w = 1 - smooth(0, 170, Math.hypot(Math.max(u, 0), Math.max(v, 0)));
        h += (ap.h - h) * w; this.apw[k] = Math.max(this.apw[k], w);
      }
      H[k] = h; this.rel[k] = h - fl;
    }

    // --- 5. Malla con colores por altura y pendiente ---
    const geo = new THREE.PlaneGeometry(HALF * 2, HALF * 2, SEG, SEG);
    geo.rotateX(-Math.PI / 2);
    const pos = geo.attributes.position as THREE.BufferAttribute;
    for (let i = 0; i < pos.count; i++) pos.setY(i, H[i]);
    geo.computeVertexNormals();
    const nor = geo.attributes.normal as THREE.BufferAttribute;
    const colors = new Float32Array(pos.count * 3);
    const C = {
      meadow: col('#76ab45'), meadow2: col('#a6c25a'), forest: col('#3a7133'), forest2: col('#55873a'),
      rock: col('#857d72'), rock2: col('#a59c90'), snow: col('#f4f7fb'), sand: col('#d6c995'), mown: col('#a5cf63'),
    };
    const c = new THREE.Color(), tmp = new THREE.Color();
    for (let i = 0; i < pos.count; i++) {
      const wx = pos.getX(i), wz = pos.getZ(i), h = H[i], r = this.rel[i];
      const sl = 1 - nor.getY(i); this.slope[i] = sl;
      const nz = vnoise(wx * 0.01, wz * 0.01, 3), nz2 = fbm(wx * 0.003, wz * 0.003, 2, 4);
      c.copy(C.meadow).lerp(C.meadow2, nz * 0.5 + nz2 * 0.5);
      c.lerp(tmp.copy(C.forest).lerp(C.forest2, nz), smooth(20, 90, r) * (0.55 + 0.45 * nz2));
      c.lerp(tmp.copy(C.rock).lerp(C.rock2, nz), Math.max(smooth(0.22, 0.42, sl), smooth(330, 470, r)));
      c.lerp(C.snow, smooth(560, 660, h + nz2 * 120) * (1 - smooth(0.5, 0.7, sl)));
      c.lerp(C.sand, smooth(WATER + 5, WATER + 1, h));
      c.lerp(C.mown, smooth(0.55, 0.9, this.apw[i]));
      colors[i * 3] = c.r; colors[i * 3 + 1] = c.g; colors[i * 3 + 2] = c.b;
    }
    geo.setAttribute('color', new THREE.BufferAttribute(colors, 3));
    const mat = new THREE.MeshPhongMaterial({ vertexColors: true, flatShading: true, shininess: 4, specular: new THREE.Color(0x101010) });
    this.group.add(new THREE.Mesh(geo, mat));
    this.owned.push(geo, mat);

    // --- 6. Agua (lagos del fondo del valle) ---
    const wg = new THREE.PlaneGeometry(HALF * 2, HALF * 2); wg.rotateX(-Math.PI / 2);
    const wm = new THREE.MeshPhongMaterial({ color: col('#2f86c4'), specular: col('#cfe8ff'), shininess: 90, transparent: true, opacity: 0.88 });
    const water = new THREE.Mesh(wg, wm); water.position.y = WATER; this.group.add(water); this.owned.push(wg, wm);

    // --- 7. Pinos (InstancedMesh, silueta escalonada por Lathe) ---
    const prof = [[0.12, 0], [0.12, 0.12], [1, 0.12], [0.45, 0.5], [0.78, 0.46], [0.25, 0.8], [0.45, 0.78], [0, 1]]
      .map(([x, y]) => new THREE.Vector2(x, y));
    const tg = new THREE.LatheGeometry(prof, 6);
    const tm = new THREE.MeshPhongMaterial({ flatShading: true, shininess: 0, specular: new THREE.Color(0) });
    const MAX = 4200; const trees = new THREE.InstancedMesh(tg, tm, MAX);
    const m4 = new THREE.Matrix4(), q = new THREE.Quaternion(), s = new THREE.Vector3(), p = new THREE.Vector3();
    const tc = [col('#2c5e2e'), col('#3a6f33'), col('#24502a'), col('#4b7d36')];
    let count = 0;
    for (let tries = 0; tries < 40000 && count < MAX; tries++) {
      const x = (R() * 2 - 1) * (HALF - 300), z = (R() * 2 - 1) * (HALF - 300);
      const gx = Math.round((x + HALF) / CELL), gz = Math.round((z + HALF) / CELL), k = gz * NV + gx;
      if (this.rel[k] < 12 || this.rel[k] > 380 || this.slope[k] > 0.32 || this.apw[k] > 0.05 || H[k] > 600) continue;
      if (fbm(x * 0.003, z * 0.003, 2, 8) < 0.42) continue;
      const hh = 9 + R() * 11;
      p.set(x, this.heightAt(x, z) - 1, z); q.setFromAxisAngle(new THREE.Vector3(0, 1, 0), R() * 6.28); s.set(hh * 0.36, hh, hh * 0.36);
      trees.setMatrixAt(count, m4.compose(p, q, s)); trees.setColorAt(count, tc[count % 4]); count++;
    }
    trees.count = count; trees.instanceMatrix.needsUpdate = true;
    if (trees.instanceColor) trees.instanceColor.needsUpdate = true;
    this.group.add(trees); this.owned.push(tg, tm);

    this.mapCanvas = this.buildMap(colors);
  }

  /** Altura del terreno (interpolación bilineal de la rejilla). */
  heightAt(x: number, z: number) {
    const fx = clamp((x + HALF) / CELL, 0, SEG - 0.001), fz = clamp((z + HALF) / CELL, 0, SEG - 0.001);
    const ix = Math.floor(fx), iz = Math.floor(fz), tx = fx - ix, tz = fz - iz, H = this.heights, k = iz * NV + ix;
    const a = H[k] + (H[k + 1] - H[k]) * tx, b = H[k + NV] + (H[k + NV + 1] - H[k + NV]) * tx;
    return a + (b - a) * tz;
  }

  /** Aeródromo cuya pista contiene el punto (con margen), o null. */
  runwayAt(x: number, z: number, margin = 8): Airport | null {
    for (const ap of this.airports) {
      const dx = x - ap.x, dz = z - ap.z;
      if (Math.abs(dx * ap.fx + dz * ap.fz) < ap.len / 2 + margin && Math.abs(dx * ap.fz - dz * ap.fx) < ap.width / 2 + margin) return ap;
    }
    return null;
  }

  pathTangent(i: number, out = new THREE.Vector3()) {
    const N = this.path.length;
    return out.subVectors(this.path[(i + 1) % N], this.path[(i - 1 + N) % N]).setY(0).normalize();
  }

  private buildMap(colors: Float32Array) {
    const S = 256, cv = document.createElement('canvas'); cv.width = cv.height = S;
    const g = cv.getContext('2d')!; const img = g.createImageData(S, S);
    for (let y = 0; y < S; y++) for (let x = 0; x < S; x++) {
      const k = Math.round((y / (S - 1)) * SEG) * NV + Math.round((x / (S - 1)) * SEG);
      const shade = 0.8 + clamp((this.heights[k] - this.heights[Math.max(0, k - NV - 1)]) * 0.012, -0.3, 0.35);
      const water = this.heights[k] < WATER, o = (y * S + x) * 4;
      const rgb = water ? [70, 150, 205] : [0, 1, 2].map(j => Math.pow(colors[k * 3 + j], 1 / 2.2) * 255 * shade);
      img.data[o] = rgb[0]; img.data[o + 1] = rgb[1]; img.data[o + 2] = rgb[2]; img.data[o + 3] = 255;
    }
    g.putImageData(img, 0, 0);
    return cv;
  }

  dispose() { this.owned.forEach(o => o.dispose()); }
}

import * as THREE from 'three';

/** Multiplica TODAS las intensidades de luz (r155+ usa unidades físicas). */
export const LIGHT_K = Number(THREE.REVISION) >= 155 ? Math.PI : 1;

// r170 activa la gestión de color por defecto; r128 no la tiene. La desactivamos para que
// THREE.Color('#hex') y la iluminación se comporten igual en ambas versiones.
const CM = (THREE as any).ColorManagement;
if (CM && typeof CM.enabled === 'boolean') CM.enabled = false;

export function setupRenderer(r: THREE.WebGLRenderer) {
  const a = r as any; const T = THREE as any;
  if ('outputColorSpace' in a) a.outputColorSpace = T.SRGBColorSpace; else a.outputEncoding = T.sRGBEncoding;
}

export function srgbTexture(t: THREE.Texture) {
  const a = t as any; const T = THREE as any;
  if ('colorSpace' in a) a.colorSpace = T.SRGBColorSpace; else a.encoding = T.sRGBEncoding;
  return t;
}

/** Color "de pantalla" (sRGB) convertido a lineal: así el hex se ve tal cual con salida sRGB. */
export function col(hex: number | string): THREE.Color {
  const c = new THREE.Color(hex as THREE.ColorRepresentation);
  c.r = Math.pow(c.r, 2.2); c.g = Math.pow(c.g, 2.2); c.b = Math.pow(c.b, 2.2);
  return c;
}

